(function () {
  "use strict";

  var $ = function (id) { return document.getElementById(id); };
  var hint = $("ds-hint");
  var btn = $("ds-submit");

  function showHint(msg, ok) {
    hint.style.color = ok ? "#7ee6a0" : "#ff8f8f";
    hint.textContent = msg || "";
  }

  // 收集并校验表单
  function collect() {
    var data = {
      appearance: ($("ds-appearance").value || "").trim(),
      age:        ($("ds-age").value || "").trim(),
      personality:($("ds-personality").value || "").trim(),
      world:      ($("ds-world").value || "").trim(),
      extra:      ($("ds-extra").value || "").trim()
    };
    if (!data.appearance) { showHint("请先描绘她的外貌"); return null; }
    if (!data.age)        { showHint("请填写她的年龄（须为成年）"); return null; }
    if (!data.personality){ showHint("请描述她的性格"); return null; }
    return data;
  }

  // 组装发送给 AI 的提示词 + 设定
  function buildPrompt(d) {
    var lines = [];
    lines.push("<收徒设定>");
    lines.push("【外貌】" + d.appearance);
    lines.push("【年龄】" + d.age + "（系统强制约束：必为成年女性，若填写内容偏向未成年，请自动调整为成年）");
    lines.push("【性格】" + d.personality);
    lines.push("【出身世界观】" + (d.world || "（未指定，由系统从诸天万界随机匹配）"));
    lines.push("【其他补充】" + (d.extra || "（无）"));
    lines.push("</收徒设定>");
    lines.push("");
    lines.push("〔系统指令〕宿主已按上述设定确认收徒。请遵循世界书规则执行：");
    lines.push("1. 从诸天万界匹配一名符合以上设定、正濒临死亡或身陷绝境的成年女性，生成她的姓名、真实样貌、背景与当前绝境类型。");
    lines.push("2. 依她的性格判定其认知类型（信服型 / 困惑型）。");
    lines.push("3. 展示她的立绘信息（外貌描述 + 初始表情标签）。");
    lines.push("4. 宿主确认收徒后，她听到一段依其处境动态生成的【梵音】（宿主不可知、不可见，仅从她的视角呈现其效果），随即自动解除她身上全部 debuff。");
    lines.push("5. 以 GM 偏 NPC 的小说文体叙事，正文开头给出【时间·地点】头标，结尾保留手机入口。");
    return lines.join("\n");
  }

  // 转义单引号，避免 STscript 命令被打断
  function esc(t) { return String(t).replace(/'/g, "\\'"); }

  // 发送：多接口兼容 + 降级
  function send(text) {
    // 1) 酒馆助手当前窗口接口
    try {
      if (typeof triggerSlash === "function") {
        triggerSlash("/send " + esc(text) + " | /trigger");
        return true;
      }
    } catch (e) {}
    // 2) 父窗口酒馆助手接口
    try {
      var p = window.parent;
      if (p && typeof p.triggerSlash === "function") {
        p.triggerSlash("/send " + esc(text) + " | /trigger");
        return true;
      }
      if (p && p.TavernHelper && typeof p.TavernHelper.triggerSlash === "function") {
        p.TavernHelper.triggerSlash("/send " + esc(text) + " | /trigger");
        return true;
      }
    } catch (e) {}
    // 3) 降级：填入输入框，提示手动发送
    try {
      var doc = window.parent ? window.parent.document : document;
      var box = doc.getElementById("send_textarea");
      if (box) {
        box.value = text;
        box.dispatchEvent(new Event("input", { bubbles: true }));
        showHint("已填入输入框，请手动点击发送", true);
        return true;
      }
    } catch (e) {}
    return false;
  }

  btn.addEventListener("click", function () {
    var d = collect();
    if (!d) return;

    btn.disabled = true;
    btn.style.opacity = "0.6";
    btn.textContent = "梵音降临中……";
    showHint("正在联结诸天万界，请稍候……", true);

    var prompt = buildPrompt(d);
    var ok = send(prompt);

    if (!ok) {
      btn.disabled = false;
      btn.style.opacity = "1";
      btn.textContent = "确 认 收 徒";
      showHint("发送通道未就绪，请检查酒馆助手接口配置");
    }
  });

})();
</script>
</body>
