/* ============================================================
 * 可爱徒弟系统 · DB Core（数据库脚本）v7.1
 * 依赖：JS-Slash-Runner（酒馆助手）
 * 职责：真正的数据库 —— 存储 / 版本回溯 / 路径式标记解析 /
 *       字段仲裁 / 增量账本 / 主副API分发 / injectPrompts 直接注入 / 人物库
 * 对外：window.DZDB
 * ------------------------------------------------------------
 * 本文件覆盖 P1(地基) + P2(数据层)。P3(智能层)在 P2 接口定型后续写。
 * 设计原则：能脚本处理的不依赖AI｜路径树同构数据库｜逐行容错｜半年稳定。
 * ------------------------------------------------------------
 * v7.1 大更新（基准 v7.0）：
 *  【M1】多域数据结构（DB_VER=2）：head.active/worlds/disciples/host，
 *        兼容层 _rebindActive 让 head.disciple/head.aff 指向活跃徒弟。
 *  【M2】成就引擎：11 条内置定义（6 徒弟 + 5 宿主），硬规则自动扫描 +
 *        AI 白名单声明 API，unlock/scan/list/hasAchievement 等 6 个 API。
 *  【M3】数据管理：dbDiagnose 四层三态灯、dbAutoFix、dbGC、dbExport、
 *        dbImport（overwrite/merge），共 5 个新 API。
 *  【M6】API 合规：injectPrompts 字段 should_scan 双写兼容
 *        （JS-Slash-Runner v1.14.0 官方规范）。
 * ============================================================ */
$(() => {
  'use strict';

  /* ---------- 顶层窗口探测（与小手机脚本一致，拿到含 #chat 的窗口） ---------- */
  var W = window, D = document;
  try {
    var w = window;
    for (var i = 0; i < 6 && w; i++) {
      if (w.document && w.document.getElementById('chat')) { W = w; break; }
      w = (w.parent && w.parent !== w) ? w.parent : null;
    }
    D = W.document;
  } catch (e) { W = window; D = document; }

  function toast(type, msg) { try { toastr && toastr[type] && toastr[type](msg); } catch (_) {} }

  /* ============================================================
   * 【P1.1】命名空间 + ready 握手信号
   * ============================================================ */
  var DZDB = W.DZDB = W.DZDB || {};
  var _readyResolve;
  DZDB.ready = new Promise(function (r) { _readyResolve = r; });

  /* ============================================================
   * 【P1.5】降级开关（inject 主路 / lorebook 降级）
   * ============================================================ */
  DZDB.mode = 'inject';       // 'inject' | 'lorebook'
  DZDB.__injectOK = null;     // null=未测 true=可用 false=不可用
  /* ---------- 诊断层：定位契约漂移导致的静默丢弃 ----------
   * DZDB.debug=true 时打印被丢弃/拒绝的写入；
   * DZDB.__dropped 环形保留最近 50 条被丢弃记录，供事后审计（无需开 debug 也记录）。
   * 排障用法：console 里看 window.DZDB.__dropped，即可知道哪个 path 因何被丢。 */
  DZDB.debug = false;
  DZDB.__dropped = [];
  function dlog() {
    if (!DZDB.debug) return;
    try { console.warn.apply(console, ['[DZDB]'].concat([].slice.call(arguments))); } catch (_) {}
  }
  function dropRec(reason, path, val) {
    try {
      DZDB.__dropped.unshift({ at: Date.now(), reason: reason, path: path, val: val });
      DZDB.__dropped = DZDB.__dropped.slice(0, 50);
    } catch (_) {}
    dlog('丢弃写入 [' + reason + ']', path, val);
  }

  /* ============================================================
   * 【P2.1】M0 存储结构与读写封装
   *  根结构五域，与路径命名空间一一对应：
   *    head.host / head.disciple / head.meta / head.npc / head.phone
   * ============================================================ */
  var DB_NS = 'DZDB_DATA';
  var DB_OPT = { type: 'chat' };
  var DB_VER = 3;
  var HIST_MAX = 30;
  var DISCIPLE_MAX = 9;      // 徒弟软上限（3x3 网格）

  /* ---------- 多域结构的构造子（M1） ---------- */
  function _newWorld(id, name) {
    return {
      id: id || 'w_default',
      name: name || '徒界',
      tone: '',
      era: '入门元年',
      npcs: [],
      timeline: [],
      places: [],
      factions: [],   // 预留（C 完整集时启用）
      genre: ''       // 预留
    };
  }
  function _newDisciple(id, worldId) {
    return {
      id: id || 'd_default',
      worldId: worldId || 'w_default',
      name:'', age:'', sex:'', appearance:'', personality:'', world:'', plight:'',
      cognitionType:'', emotion:'calm', mood:'', status:'安好', storyline:'',
      locale:'', belongings:[], backlog:[],
      aff: { level: 0, value: 0 },
      bond: { tier: 0, pactItem: '', pactDay: 0, events: [] },
      achievements: [],     // 徒弟私有成就
      // 【M8】寻徒占位字段：宿主发起寻徒时创建的空位，AI 后续揭示身份/名字
      summonIntent: '',     // 宿主招募时给 AI 的意向短语（可留空）
      summonedAt: 0,        // 招募时的剧情日；0 表示未招募（初始 d_default）
      revealed: false       // AI 是否已揭示（name 非空时自动置 true）
    };
  }

  /* ---------- 活跃徒弟引用绑定（M1 兼容层） ----------
   * head.disciple / head.aff 始终指向当前活跃徒弟对象；
   * 这样老 UI 代码里的 d.disciple.xxx / d.aff.level 无需修改就能透明工作。
   * 切换活跃徒弟时必须重新调用 _rebindActive。
   */
  function _rebindActive(head) {
    if (!head) return;
    var did = head.active && head.active.discipleId;
    var d = null;
    if (head.disciples && head.disciples.length) {
      for (var i = 0; i < head.disciples.length; i++) {
        if (head.disciples[i] && head.disciples[i].id === did) { d = head.disciples[i]; break; }
      }
      if (!d) d = head.disciples[0];
      if (head.active) head.active.discipleId = d.id;
    }
    if (!d) { head.disciple = null; head.aff = { level:0, value:0 }; return; }
    head.disciple = d;                     // 活跃徒弟对象（引用同步）
    if (!d.aff) d.aff = { level: 0, value: 0 };
    head.aff = d.aff;                      // UI 里 d.aff.{level,value} 直接落到活跃徒弟
    if (head.host) {
      head.host.affLevel = d.aff.level;    // 兼容老字段镜像（只读，勿作为真源写入）
      head.host.affValue = d.aff.value;
    }
  }

  function dbDefault() {
    var w = _newWorld('w_default', '徒界');
    var d = _newDisciple('d_default', 'w_default');
    var obj = {
      ver: DB_VER,
      head: {
        active:   { discipleId: 'd_default' },
        worlds:   [w],
        disciples:[d],
        host:     { name:'', balance: 500, coin: 0, rebateLog: [],
                    touchLeft: 5, talkLeft: 1, quotaDay: 1,
                    affLevel: 0, affValue: 0,     // 兼容老字段镜像，真源在 disciples[i].aff
                    achievements: [] },           // 宿主全局成就
        meta:     { day:1, gameDay:1, lastRealDay:1, period:'', place:'', cognition:'懵懂',
                    lastCatchUp:null, recentGiven:[] },
        npc:      {},
        phone:    { generated:false, day:0, shop:[], news:[], bag:[], deletedContacts:[], grievances:[], seenBacklog:0 },
        ui:       { api2:{enabled:false,url:'',key:'',model:'',source:'openai',models:[]},
                    auto:{enabled:true,interval:3,counter:0},
                    live2d:{enabled:true,modelUrl:''},
                    quota:{touchLeft:5,talkLeft:1,lastDay:1},
                    pendingActs:[], shopRefresh:false, dayStart:0 }
      },
      history: []
    };
    _rebindActive(obj.head);
    return obj;
  }
  var _dbCache = null;

  function dbLoadRaw() {
    var all = {};
    try { all = getVariables(DB_OPT) || {}; } catch (e) {}
    var obj = all[DB_NS];
    if (!obj || typeof obj !== 'object' || !obj.head) obj = dbDefault();
    obj = dbMigrate(obj);
    _dbCache = obj;
    return obj;
  }
  function dbSaveRaw(obj) {
    _dbCache = obj;
    var p = {}; p[DB_NS] = obj;
    try { insertOrAssignVariables(p, DB_OPT); }
    catch (e) { console.error('[DZDB] 保存失败', e); }
  }

  /* ============================================================
   * 版本化迁移步骤表（MIGRATIONS）
   * ------------------------------------------------------------
   * 关键约定：DB_VER 每次“字段语义/类型/结构”变更时 +1，并在此登记
   * 一个 from->to 的升级函数。dbMigrate 会按 obj.ver 顺序补跑所有
   * 缺失的步骤，从而修正老存档里带旧语义的数据（而非仅补缺失字段）。
   *
   * 步骤函数签名：function(head){ ...就地改写 head... }
   * 键为“目标版本号”：键 N 表示“把 ver=N-1 的数据升级到 ver=N”。
   * 例（将来真正改结构时的写法，勿留空跑）：
   *   2: function(head){ // 例：status 枚举“交战”改名“战斗”
   *        if (head.disciple.status === '交战') head.disciple.status = '战斗';
   *      },
   *   3: function(head){ // 例：balance 从数字改为 {amount,currency}
   *        if (typeof head.host.balance === 'number')
   *          head.host.balance = { amount: head.host.balance, currency: 'CNY' };
   *      },
   * ============================================================ */
  var MIGRATIONS = {
    /* v2：单徒弟 → 多徒弟 + 世界独立域 + 双层成就
     * 老结构：head.disciple / head.host.{affLevel,affValue}
     * 新结构：head.active + head.worlds[] + head.disciples[]，disciple 私域下沉 aff/achievements
     * 兼容：head.disciple / head.aff 通过 _rebindActive 保留为活跃徒弟的引用（老 UI 无需改）
     */
    2: function (head) {
      // 1) 构造默认世界（tone 从老 disciple.world 提炼作为世界基调）
      var oldD = (head.disciple && typeof head.disciple === 'object') ? head.disciple : {};
      var w = _newWorld('w_default', '徒界');
      if (oldD.world) w.tone = String(oldD.world).slice(0, 200);
      head.worlds = [w];

      // 2) 老徒弟迁到 disciples[0]，补新字段
      var d = _newDisciple('d_default', 'w_default');
      ['name','age','sex','appearance','personality','world','plight','cognitionType',
       'emotion','mood','status','storyline','locale'].forEach(function (k) {
        if (oldD[k] != null) d[k] = oldD[k];
      });
      if (Array.isArray(oldD.belongings)) d.belongings = oldD.belongings;
      if (Array.isArray(oldD.backlog))    d.backlog    = oldD.backlog;
      // 3) 羁绊从 host.affLevel/affValue 下沉到 disciples[0].aff（真源迁移）
      var h = head.host || {};
      d.aff = {
        level: (typeof h.affLevel === 'number') ? h.affLevel : 0,
        value: (typeof h.affValue === 'number') ? h.affValue : 0
      };
      d.achievements = [];
      head.disciples = [d];

      // 4) 活跃指针
      head.active = { discipleId: 'd_default' };

      // 5) 宿主全局成就初始化
      if (!head.host) head.host = {};
      if (!Array.isArray(head.host.achievements)) head.host.achievements = [];

      // 6) 老顶层字段清理（head.disciple 会在 rebind 时重挂为 disciples[0] 的引用）
      //    这里不 delete，让 rebind 覆盖为引用即可
    },
    /* v3：新增 disciple.bond 字段（道侣段位扩展）
     * 给每个已有徒弟补充 bond 默认值 */
    3: function (head) {
      (head.disciples || []).forEach(function (d) {
        if (d && (d.bond == null || typeof d.bond !== 'object')) {
          d.bond = { tier: 0, pactItem: '', pactDay: 0, events: [] };
        }
      });
    }
  };
  /* 迁移：先按版本号补跑升级步骤（修正旧语义），再补齐缺失域/字段（结构保险） */
  function dbMigrate(obj) {
    var def = dbDefault();
    if (obj.head == null || typeof obj.head !== 'object') obj.head = def.head;
    /* --- 第一步：版本化升级（修正老存档旧语义/旧类型） --- */
    var from = (typeof obj.ver === 'number' && obj.ver >= 1) ? obj.ver : 1;
    if (from > DB_VER) {
      // 存档比当前脚本还新（用户回退了脚本版本）：不降级改写，仅记录告警
      dlog('存档版本(' + from + ') 高于脚本(' + DB_VER + ')，跳过升级，仅做结构保险');
    } else {
      for (var v = from + 1; v <= DB_VER; v++) {
        var step = MIGRATIONS[v];
        if (typeof step !== 'function') continue;
        try { step(obj.head); dlog('迁移升级 ' + (v - 1) + ' -> ' + v + ' 完成'); }
        catch (e) { try { console.error('[DZDB] 迁移步骤 ' + v + ' 失败', e); } catch (_) {} }
      }
    }
    /* --- 第二步：结构保险（补齐缺失域/字段，不覆盖已有） ---
     * 注意：head.disciple / head.aff 是 rebind 出来的引用，不参与结构保险枚举
     */
    ['host','meta','npc','phone','ui'].forEach(function (dom) {
      if (obj.head[dom] == null || typeof obj.head[dom] !== 'object') obj.head[dom] = def.head[dom];
      Object.keys(def.head[dom]).forEach(function (k) {
        if (obj.head[dom][k] == null) obj.head[dom][k] = def.head[dom][k];
      });
    });
    // active / worlds / disciples 域保险
    if (!obj.head.active || typeof obj.head.active !== 'object') obj.head.active = { discipleId: '' };
    if (!Array.isArray(obj.head.worlds) || obj.head.worlds.length === 0) {
      obj.head.worlds = [_newWorld('w_default', '徒界')];
    }
    if (!Array.isArray(obj.head.disciples) || obj.head.disciples.length === 0) {
      obj.head.disciples = [_newDisciple('d_default', obj.head.worlds[0].id)];
      obj.head.active.discipleId = 'd_default';
    }
    // 每个徒弟补新字段（不覆盖已有）
    obj.head.disciples.forEach(function (dd) {
      if (!dd.aff || typeof dd.aff !== 'object') dd.aff = { level: 0, value: 0 };
      if (typeof dd.aff.level !== 'number') dd.aff.level = 0;
      if (typeof dd.aff.value !== 'number') dd.aff.value = 0;
      if (!Array.isArray(dd.achievements)) dd.achievements = [];
      if (!dd.bond || typeof dd.bond !== 'object') dd.bond = { tier: 0, pactItem: '', pactDay: 0, events: [] };
      if (typeof dd.bond.tier !== 'number') dd.bond.tier = 0;
      if (typeof dd.bond.pactItem !== 'string') dd.bond.pactItem = '';
      if (typeof dd.bond.pactDay !== 'number') dd.bond.pactDay = 0;
      if (!Array.isArray(dd.bond.events)) dd.bond.events = [];
      if (!Array.isArray(dd.belongings))   dd.belongings   = [];
      if (!Array.isArray(dd.backlog))      dd.backlog      = [];
      if (!dd.id) dd.id = 'd_' + Math.random().toString(36).slice(2, 8);
      if (!dd.worldId) dd.worldId = obj.head.worlds[0].id;
      if (typeof dd.sex !== 'string') dd.sex = '';
    });
    // 每个世界补新字段
    obj.head.worlds.forEach(function (ww) {
      if (!Array.isArray(ww.npcs))     ww.npcs     = [];
      if (!Array.isArray(ww.timeline)) ww.timeline = [];
      if (!Array.isArray(ww.places))   ww.places   = [];
      if (!Array.isArray(ww.factions)) ww.factions = [];
      if (typeof ww.tone !== 'string')  ww.tone  = '';
      if (typeof ww.era  !== 'string')  ww.era   = '入门元年';
      if (typeof ww.genre !== 'string') ww.genre = '';
      if (!ww.id)   ww.id   = 'w_' + Math.random().toString(36).slice(2, 8);
      if (!ww.name) ww.name = '未命名世界';
    });
    // 宿主成就簿保险
    if (!Array.isArray(obj.head.host.achievements)) obj.head.host.achievements = [];

    if (!Array.isArray(obj.history)) obj.history = [];
    if (!Array.isArray(obj.head.host.rebateLog))       obj.head.host.rebateLog = [];
    if (!Array.isArray(obj.head.phone.shop))            obj.head.phone.shop = [];
    if (!Array.isArray(obj.head.phone.news))            obj.head.phone.news = [];
    if (!Array.isArray(obj.head.phone.bag))             obj.head.phone.bag = [];
    if (!Array.isArray(obj.head.phone.deletedContacts)) obj.head.phone.deletedContacts = [];
    if (!Array.isArray(obj.head.phone.grievances))      obj.head.phone.grievances = [];
    if (!Array.isArray(obj.head.ui.pendingActs))        obj.head.ui.pendingActs = [];

    // 最后：把 head.disciple / head.aff 绑到活跃徒弟（老 UI 透明兼容层）
    _rebindActive(obj.head);

    // 只把版本推进到“脚本版本 与 存档原版本 的较大值”，不误降级更新的存档
    obj.ver = Math.max(DB_VER, from);
    return obj;
  }

  /* ============================================================
   * 【P2.2】M0 版本历史与回溯
   * ============================================================ */
  function deepClone(o) { try { return JSON.parse(JSON.stringify(o)); } catch (_) { return null; } }

  function dbSnapshot(mid) {
    try {
      var obj = dbLoadRaw();
      var snap = { mid: mid, at: Date.now(), data: deepClone(obj.head) };
      if (!snap.data) return;
      // 同 mid 覆盖（重roll 同层）
      obj.history = (obj.history || []).filter(function (h) { return h.mid !== mid; });
      obj.history.push(snap);
      if (obj.history.length > HIST_MAX) obj.history = obj.history.slice(-HIST_MAX);
      dbSaveRaw(obj);
    } catch (e) { console.error('[DZDB] 快照失败', e); }
  }
  function dbRestore(mid) {
    try {
      var obj = dbLoadRaw();
      var hist = obj.history || [];
      if (!hist.length) return false;
      // 找 mid 精确匹配，否则找 <=mid 中最大的
      var hit = null;
      for (var i = 0; i < hist.length; i++) {
        if (hist[i].mid === mid) { hit = hist[i]; break; }
        if (hist[i].mid <= mid && (!hit || hist[i].mid > hit.mid)) hit = hist[i];
      }
      if (!hit || !hit.data) return false;
      obj.head = deepClone(hit.data);
      dbSaveRaw(obj);
      return true;
    } catch (e) { console.error('[DZDB] 回溯失败', e); return false; }
  }

  /* ============================================================
   * 【P2.3】M0 路径读写原语（点号路径，自动建中间层）
   * ============================================================ */
  function pathParts(path) { return String(path).split('.').filter(Boolean); }

  function dbGet(path) {
    var obj = dbLoadRaw();
    var o = obj.head, ps = pathParts(path);
    for (var i = 0; i < ps.length; i++) {
      if (o == null || typeof o !== 'object') return undefined;
      o = o[ps[i]];
    }
    return o;
  }
  // 在给定 head 上直接 set（不 load/save，供批量内部用）
  function setOnHead(head, path, val) {
    var ps = pathParts(path), o = head;
    for (var i = 0; i < ps.length - 1; i++) {
      if (typeof o[ps[i]] !== 'object' || o[ps[i]] == null) o[ps[i]] = {};
      o = o[ps[i]];
    }
    o[ps[ps.length - 1]] = val;
  }
  function dbSet(path, val) {
    var obj = dbLoadRaw();
    setOnHead(obj.head, path, val);
    dbSaveRaw(obj);
  }
  function getOnHead(head, path) {
    var o = head, ps = pathParts(path);
    for (var i = 0; i < ps.length; i++) { if (o == null) return undefined; o = o[ps[i]]; }
    return o;
  }

  /* ============================================================
   * 【P2.4】M1 字段仲裁（路径前缀 → owner）
   *  owner: main=仅主API | phone=仅副API | arb=双写 | lock=空时可写非空锁定 | npc=脚本管
   * ============================================================ */
  var OWNER_EXACT = {
    'disciple.name':'lock', 'disciple.age':'lock', 'disciple.appearance':'lock',
    'disciple.personality':'lock', 'disciple.world':'lock', 'disciple.plight':'lock',
    'disciple.cognitionType':'lock', 'disciple.sex':'lock',
    'disciple.status':'arb', 'disciple.storyline':'arb', 'disciple.emotion':'arb',
    'disciple.mood':'arb', 'disciple.locale':'arb'
  };
  var OWNER_PREFIX = [
    ['host.',     'main'],
    ['meta.',     'main'],
    ['disciple.', 'main'],   // 兜底：未在 EXACT 命中的 disciple.* 归 main（含 disciple.aff.*）
    ['npc.',      'npc'],
    ['phone.',    'phone']
    // 注意：active. / worlds. / disciples.（顶层数组）故意不在表内，
    // 使 commit 走 no-owner 拦截，强制通过专用 API 修改
  ];
  function resolveOwner(path) {
    if (OWNER_EXACT[path]) return OWNER_EXACT[path];
    for (var i = 0; i < OWNER_PREFIX.length; i++) {
      if (path.indexOf(OWNER_PREFIX[i][0]) === 0) return OWNER_PREFIX[i][1];
    }
    // 【M8】disciples[i].field / disciples.i.field —— 复用 disciple.field 的 owner 规则
    // 这样 AI 揭示徒弟身份时可以直接写 disciples[i].name/appearance/...
    var m = path.match(/^disciples(?:\[\d+\]|\.\d+)\.(.+)$/);
    if (m) {
      var proj = 'disciple.' + m[1];
      if (OWNER_EXACT[proj]) return OWNER_EXACT[proj];
      // 兜底：disciples[i].aff.value / .aff.level 等归 main
      return 'main';
    }
    return null;
  }
  // 【M8】数组路径 → 拍平路径，供 sanitizeValue 复用规则
  function _projPath(path) {
    var m = path.match(/^disciples(?:\[\d+\]|\.\d+)\.(.+)$/);
    return m ? ('disciple.' + m[1]) : path;
  }

  /* ============================================================
   * 【P2.5】M1 sanitize / 枚举 / 长度
   * ============================================================ */
  var NUM_RULE = {
    'host.affLevel':[0,99,true], 'host.affValue':[0,100,true],
    'host.touchLeft':[0,999,true], 'host.talkLeft':[0,999,true],
    'meta.day':[1,1e6,true],
    // 羁绊真源（活跃徒弟私域），走引用透传到 disciples[active].aff
    'disciple.aff.level':[0,99,true], 'disciple.aff.value':[0,100,true]
  };
  var STR_MAX = {
    'disciple.mood':60, 'disciple.emotion':12, 'disciple.storyline':60, 'disciple.locale':40,
    'disciple.name':24, 'disciple.age':12, 'disciple.appearance':200, 'disciple.personality':80,
    'disciple.world':40, 'disciple.plight':60, 'disciple.cognitionType':8, 'disciple.sex':4,
    'meta.cognition':8, 'meta.period':8, 'meta.place':40
  };
  var EMOTION_SET = ['happy','shy','sad','angry','cry','calm'];
  var STATUS_SET  = ['安好','修炼','闭关','赶路','交战','受伤','遇险','脱困','失踪'];
  // 结构化字段整体写入拦截：这些字段必须通过专用 API 修改（achievements → unlockAchievement；aff → dbAff）
  var BLOCK_WHOLE_WRITE = {
    'disciple.achievements': true,
    'host.achievements':     true,
    'disciple.aff':          true,
    'disciple.bond':         true
  };

  function sanNum(val, min, max, isInt) {
    var n = Number(val);
    if (!isFinite(n)) return undefined;
    if (isInt) n = Math.round(n);
    if (min != null) n = Math.max(min, n);
    if (max != null) n = Math.min(max, n);
    return n;
  }
  function sanStr(val, maxLen) {
    if (val == null || typeof val === 'object') return undefined;
    var s = String(val).trim();
    if (!s) return undefined;
    if (maxLen && s.length > maxLen) s = s.slice(0, maxLen);
    return s;
  }
  // 返回清洗后的值，或 undefined 表示拒绝
  function sanitizeValue(path, val) {
    // M8：disciples[i].xxx 拍平到 disciple.xxx 复用规则
    var p = _projPath(path);
    // 结构化字段整体写入拦截（必须走专用 API）
    if (BLOCK_WHOLE_WRITE[p]) return undefined;
    if (NUM_RULE[p]) { var r = NUM_RULE[p]; return sanNum(val, r[0], r[1], r[2]); }
    if (p === 'disciple.emotion') { var e = sanStr(val,12); return (e && EMOTION_SET.indexOf(e)>=0) ? e : undefined; }
    if (p === 'disciple.status')  { var st = sanStr(val,8); return (st && STATUS_SET.indexOf(st)>=0) ? st : undefined; }
    if (STR_MAX[p] != null) return sanStr(val, STR_MAX[p]);
    return val; // 无规则字段原样（npc.* 等由各自逻辑管）
  }

  /* ============================================================
   * 【P2.3+P2.4+P2.5】dbCommit：批量路径写入（含仲裁+校验）
   * ============================================================ */
  function dbCommit(patch, source) {
    if (!patch || typeof patch !== 'object') return;
    var obj = dbLoadRaw();
    var changed = false, levelUp = 0;
    Object.keys(patch).forEach(function (path) {
      var owner = resolveOwner(path);
      if (!owner) { dropRec('no-owner', path, patch[path]); return; }
      var val = sanitizeValue(path, patch[path]);
      if (val === undefined) { dropRec('sanitize-reject', path, patch[path]); return; }
      if (owner === 'lock') {
        // lock = 仅 main 且当前为空时可写（收徒身份只由主API确立，副API 永不可碰）
        if (source !== 'main') { dropRec('lock-src(' + source + ')', path, val); return; }
        var cur = getOnHead(obj.head, path);
        if (cur == null || cur === '') { setOnHead(obj.head, path, val); changed = true; }
        else { dropRec('lock-occupied', path, val); }
        return;
      }
      if (owner === 'arb') { setOnHead(obj.head, path, val); changed = true; return; }
      if (owner === 'npc') { setOnHead(obj.head, path, val); changed = true; return; }
      if (owner !== source) { dropRec('owner(' + owner + ')!=src(' + source + ')', path, val); return; } // main/phone 归属校验
      setOnHead(obj.head, path, val); changed = true;
    });
    // 【M8】名字揭示钩子：AI 通过 <状态> 写入 disciple[].name 或 disciple.name 时，
    // 把 revealed 置为 true 并立即扫描一次成就（触发 h_first / d_meet 等硬规则）
    if (changed) {
      var reveals = 0;
      Object.keys(patch).forEach(function(p){
        // 兼容路径：head.disciple.name / head.disciples[i].name / 'disciple.name' / 'disciples[i].name'
        if (/(^|\.)disciples?(\[\d+\])?\.name$/.test(p)) reveals++;
      });
      if (reveals > 0 && obj.head && obj.head.disciples) {
        obj.head.disciples.forEach(function(d){
          if (d && d.name && !d.revealed) d.revealed = true;
        });
        try { _scanAutoOn(obj.head); } catch(_){}
      }
      dbSaveRaw(obj);
    }
    return changed;
  }

  /* ============================================================
   * 【P2.6】M1 增量账本（余额 / 好感）
   * ============================================================ */
  var _affLevelUpCb = null;
  DZDB.onAffLevelUp = function (fn) { _affLevelUpCb = fn; };

  function dbBalance(delta, why, kind) {
    delta = sanNum(delta, -1e12, 1e12, true);
    if (delta === undefined || delta === 0) return;
    var obj = dbLoadRaw();
    var before = Number(obj.head.host.balance) || 0;
    var after = before + delta;
    if (after < 0) after = 0;
    obj.head.host.balance = after;
    if (delta > 0) {
      obj.head.host.rebateLog.unshift({ day: obj.head.meta.day, amt: delta, why: why || (kind==='rebate'?'返利':'入账') });
      obj.head.host.rebateLog = obj.head.host.rebateLog.slice(0, 30);
    }
    dbSaveRaw(obj);
  }
  /* M2 修复：羁绊真源已下沉到活跃徒弟。normAffDisciple 就地规范化徒弟的 aff 对象，
   * 并把结果镜像回 head.host（供老 UI 只读）。返回本次跨级次数（0 表示未升级）。 */
  function normAffDisciple(d, head) {
    if (!d || !d.aff) return 0;
    var leveled = 0;
    while (d.aff.value >= 100 && d.aff.level < 99) { d.aff.value -= 100; d.aff.level++; leveled++; }
    while (d.aff.value < 0 && d.aff.level > 0) { d.aff.value += 100; d.aff.level--; }
    if (d.aff.value > 100 && d.aff.level >= 99) d.aff.value = 100;
    if (d.aff.value < 0) d.aff.value = 0;
    // 镜像回 host 兼容字段（老 UI/prompt 读这两个字段）
    if (head && head.host) { head.host.affLevel = d.aff.level; head.host.affValue = d.aff.value; }
    return leveled;
  }
  function dbAff(delta) {
    delta = sanNum(delta, -1e6, 1e6, true);
    if (delta === undefined || delta === 0) return;
    var obj = dbLoadRaw();
    var d = obj.head.disciple;                   // _rebindActive 已把活跃徒弟绑到 head.disciple
    if (!d) return;
    if (!d.aff) d.aff = { level: 0, value: 0 };
    d.aff.value += delta;
    var lv = normAffDisciple(d, obj.head);
    // 羁绊变化后扫描徒弟私有成就（硬规则：达到 Lv3/5/8 等）
    try { _scanAutoOn(obj.head, 'disciple', d.id); } catch (_) {}
    dbSaveRaw(obj);
    if (lv > 0 && typeof _affLevelUpCb === 'function') {
      try { _affLevelUpCb(d.aff.level); } catch (_) {}
    }
  }

  /* ============================================================
   * 【道侣段位】bond API — Lv.6~10 晋升管理
   * ============================================================ */

  // 获取某位徒弟的道侣段位状态
  // 返回 { tier, canUpgrade, reason, needItem, needEvents, nextName }
  function getBondStatus(discipleId) {
    var obj = dbLoadRaw();
    var ds = obj.head.disciples || [];
    var d = null;
    for (var i = 0; i < ds.length; i++) {
      if (ds[i] && ds[i].id === discipleId) { d = ds[i]; break; }
    }
    if (!d) return null;
    var bond = d.bond || { tier: 0, pactItem: '', pactDay: 0, events: [] };
    var curTier = bond.tier;
    // tier=0 且 aff.level<5 — 未达标
    if (curTier === 0) {
      if ((d.aff && d.aff.level) < 5) {
        return { tier: 0, canUpgrade: false, reason: '好感等级未达 Lv.5',
                 needItem: '逆天级道具', needEvents: [], nextName: '灵契' };
      }
      return { tier: 0, canUpgrade: true, reason: '',
               needItem: '逆天级道具', needEvents: [], nextName: '灵契' };
    }
    // curTier >= 6：检查能否升下一级
    var nextTier = curTier + 1;
    if (nextTier > 10) {
      return { tier: curTier, canUpgrade: false, reason: '已达最高段位',
               needItem: '', needEvents: [], nextName: '' };
    }
    var nextNames = { 7:'心印', 8:'同命', 9:'道侣', 10:'共命' };
    // 好感满 100？
    var affFull = d.aff && d.aff.value >= 100 && d.aff.level >= curTier;
    // Lv.8+ 需要剧情事件
    var needEvents = (nextTier >= 9) ? [ 'bond_evt_' + nextTier ] : [];
    var hasEvents = needEvents.every(function(eid) {
      return bond.events && bond.events.indexOf(eid) >= 0;
    });
    if (!affFull) {
      return { tier: curTier, canUpgrade: false,
               reason: '好感未满（需 Lv.' + curTier + ' 100%）',
               needItem: '逆天级道具', needEvents: needEvents, nextName: nextNames[nextTier] || '' };
    }
    if (needEvents.length && !hasEvents) {
      return { tier: curTier, canUpgrade: false,
               reason: '缺少关键剧情事件',
               needItem: '逆天级道具', needEvents: needEvents, nextName: nextNames[nextTier] || '' };
    }
    return { tier: curTier, canUpgrade: true, reason: '',
             needItem: '逆天级道具', needEvents: needEvents, nextName: nextNames[nextTier] || '' };
  }

  // 执行道侣段位晋升
  // discipleId — 目标徒弟ID
  // itemName — 消耗的逆天道具名（从背包扣除）
  // 返回 { success, error, newTier }
  function upgradeBond(discipleId, itemName) {
    var status = getBondStatus(discipleId);
    if (!status) return { success: false, error: '徒弟不存在' };
    if (!status.canUpgrade) return { success: false, error: status.reason };

    var obj = dbLoadRaw();
    var d = null;
    for (var i = 0; i < obj.head.disciples.length; i++) {
      if (obj.head.disciples[i] && obj.head.disciples[i].id === discipleId) {
        d = obj.head.disciples[i]; break;
      }
    }
    if (!d) return { success: false, error: '徒弟不存在' };
    if (!d.bond) d.bond = { tier: 0, pactItem: '', pactDay: 0, events: [] };

    // 从背包扣除道具
    var bag = obj.head.phone.bag || [];
    var idx = -1;
    for (var bi = 0; bi < bag.length; bi++) {
      if (bag[bi] && bag[bi].name === itemName) { idx = bi; break; }
    }
    if (idx < 0) return { success: false, error: '背包中没有「' + itemName + '」' };
    var item = bag[idx];
    var qty = item.qty || 1;
    if (qty <= 1) bag.splice(idx, 1);
    else item.qty = qty - 1;

    // 晋升
    var newTier = (d.bond.tier === 0) ? 6 : (d.bond.tier + 1);
    d.bond.tier = newTier;
    d.bond.pactItem = itemName;
    d.bond.pactDay = obj.head.meta.gameDay || obj.head.meta.day || 1;
    // 好感清零（进入下一级的积累周期）
    if (d.aff) d.aff.value = 0;

    // 触发成就
    try {
      if (newTier === 6) _unlockOn(obj.head, 'd_bond6', d.id, 'auto');
      if (newTier === 9) _unlockOn(obj.head, 'd_bond9', d.id, 'auto');
      // 检查全段位制霸（所有徒弟都 Lv.10）
      var allAt10 = (obj.head.disciples || []).every(function(x) {
        return x && x.name && x.bond && x.bond.tier >= 10;
      });
      if (allAt10) _unlockOn(obj.head, 'h_grandmaster', null, 'auto');
    } catch (_) {}

    dbSaveRaw(obj);
    // 触发升级回调（弹窗）
    try {
      if (typeof _affLevelUpCb === 'function') _affLevelUpCb(newTier);
    } catch (_) {}

    return { success: true, error: '', newTier: newTier };
  }

  // 注册关键剧情事件（由 AI 在 <状态> 块中声明）
  // discipleId — 目标徒弟ID
  // eventId — 事件ID，如 'bond_evt_9'
  function registerBondEvent(discipleId, eventId) {
    if (!discipleId || !eventId) return false;
    var obj = dbLoadRaw();
    var d = null;
    for (var i = 0; i < obj.head.disciples.length; i++) {
      if (obj.head.disciples[i] && obj.head.disciples[i].id === discipleId) {
        d = obj.head.disciples[i]; break;
      }
    }
    if (!d) return false;
    if (!d.bond) d.bond = { tier: 0, pactItem: '', pactDay: 0, events: [] };
    if (!Array.isArray(d.bond.events)) d.bond.events = [];
    if (d.bond.events.indexOf(eventId) >= 0) return false; // 已注册
    d.bond.events.push(eventId);
    dbSaveRaw(obj);
    return true;
  }

  /* ============================================================
   * ------------------------------------------------------------
   * 双层：disciple 私有成就 + host 全局成就
   * 触发：硬规则自动扫描（scanAutoAchievements）+ AI 白名单声明式
   * 存储：disciples[i].achievements[] / host.achievements[]
   *       条目形状 { id, day, source }。整体覆盖被 BLOCK_WHOLE_WRITE 拦截，
   *       只能通过本引擎的 unlockAchievement 内部路径追加。
   * ------------------------------------------------------------ */
  var ACH_SRC_AUTO   = 'auto';    // 硬规则自动
  var ACH_SRC_AI     = 'ai';      // AI 声明（白名单校验后）
  var ACH_SRC_MANUAL = 'manual';  // 手动/调试

  // scope: 'disciple' | 'host'
  // aiClaimable: 是否允许 AI 通过声明式协议解锁（false=仅硬规则可发）
  // rule: 用于 scanAutoAchievements 的判定函数 (head, target)=>bool; null 表示纯 AI 触发
  var ACHIEVEMENT_DEFS = [
    // ---- 徒弟私有 ----
    { id:'d_meet',      scope:'disciple', title:'初见',       desc:'与徒弟正式相识。',
      aiClaimable:false, rule: function(h,d){ return !!(d && d.name); } },
    { id:'d_friend',    scope:'disciple', title:'挚友',       desc:'羁绊达到 Lv3。',
      aiClaimable:false, rule: function(h,d){ return d && d.aff && d.aff.level>=3; } },
    { id:'d_soulmate',  scope:'disciple', title:'心灵相通',   desc:'羁绊达到 Lv5。',
      aiClaimable:false, rule: function(h,d){ return d && d.aff && d.aff.level>=5; } },
    { id:'d_devoted',   scope:'disciple', title:'情深意重',   desc:'羁绊达到 Lv8。',
      aiClaimable:false, rule: function(h,d){ return d && d.aff && d.aff.level>=8; } },
    { id:'d_awaken',    scope:'disciple', title:'心境觉醒',   desc:'突破一次重大心境。',
      aiClaimable:true,  rule: null },
    { id:'d_trial',     scope:'disciple', title:'共渡难关',   desc:'与徒弟一同度过一次危机。',
      aiClaimable:true,  rule: null },

    // ---- 宿主全局 ----
    { id:'h_first',     scope:'host',     title:'初为人师',   desc:'收下第一位徒弟。',
      aiClaimable:false, rule: function(h){ return h.disciples && h.disciples.length>=1
                                                   && !!(h.disciples[0] && h.disciples[0].name); } },
    { id:'h_three',     scope:'host',     title:'桃李三分',   desc:'门下徒弟达 3 人。',
      aiClaimable:false, rule: function(h){ return (h.disciples||[]).filter(function(x){return x&&x.name;}).length>=3; } },
    { id:'h_full',      scope:'host',     title:'满门桃李',   desc:'门下徒弟达上限。',
      aiClaimable:false, rule: function(h){ return (h.disciples||[]).filter(function(x){return x&&x.name;}).length>=DISCIPLE_MAX; } },
    { id:'h_biworld',   scope:'host',     title:'跨界双主',   desc:'掌管的世界达到 2 个。',
      aiClaimable:false, rule: function(h){ return (h.worlds||[]).length>=2; } },
    { id:'h_legend',    scope:'host',     title:'一代宗师',   desc:'达成宗师级成就。',
      aiClaimable:true,  rule: null },

    // ---- 新增：道侣段位成就 ----
    { id:'d_bond6',       scope:'disciple', title:'灵契',       desc:'与徒弟缔结灵契，灵力共鸣。',
      aiClaimable:false, rule: function(h,d){ return d && d.bond && d.bond.tier >= 6; } },
    { id:'d_bond9',       scope:'disciple', title:'道侣',       desc:'与徒弟成为正式道侣，跨界无阻。',
      aiClaimable:false, rule: function(h,d){ return d && d.bond && d.bond.tier >= 9; } },
    { id:'h_grandmaster', scope:'host',     title:'全段位制霸', desc:'所有弟子均达到共命段位。',
      aiClaimable:false, rule: function(h){ return (h.disciples||[]).filter(function(x){return x&&x.name;}).length > 0
        && (h.disciples||[]).every(function(x){ return !x.name || (x.bond && x.bond.tier >= 10); }); } }
  ];

  function _achDef(id) {
    for (var i=0;i<ACHIEVEMENT_DEFS.length;i++) if (ACHIEVEMENT_DEFS[i].id===id) return ACHIEVEMENT_DEFS[i];
    return null;
  }
  function _achTargetList(head, def, targetId) {
    if (!def) return null;
    if (def.scope === 'host') return head.host.achievements || (head.host.achievements = []);
    // disciple scope: 需要 targetId，未传则用活跃
    var did = targetId || (head.active && head.active.discipleId);
    var arr = head.disciples || [];
    for (var i=0;i<arr.length;i++) {
      if (arr[i] && arr[i].id === did) {
        if (!arr[i].achievements) arr[i].achievements = [];
        return arr[i].achievements;
      }
    }
    return null;
  }
  function _achHas(list, id) {
    if (!list) return false;
    for (var i=0;i<list.length;i++) if (list[i] && list[i].id === id) return true;
    return false;
  }

  var _achUnlockCb = null;
  DZDB.onAchievementUnlock = function (fn) { _achUnlockCb = fn; };

  /* 内部：在已加载的 head 上就地解锁一枚成就。不 save，交给调用方决定何时落盘。
   * 返回 true 表示实际新增（去重后），false 表示已存在或参数无效。 */
  function _unlockOn(head, achId, targetId, source) {
    var def = _achDef(achId);
    if (!def) { dropRec('ach-unknown', achId, targetId); return false; }
    var list = _achTargetList(head, def, targetId);
    if (!list) { dropRec('ach-no-target', achId, targetId); return false; }
    if (_achHas(list, achId)) return false;
    list.push({ id: achId, day: (head.meta && head.meta.day)||1, source: source||ACH_SRC_MANUAL });
    if (typeof _achUnlockCb === 'function') {
      try { _achUnlockCb(def, def.scope === 'host' ? null : (targetId || (head.active&&head.active.discipleId))); } catch(_){}
    }
    return true;
  }

  /* 内部：在已加载的 head 上扫描硬规则并批量解锁。
   * scope: undefined | 'disciple' | 'host' —— 缩小扫描范围避免开销
   * targetId: 仅 scope='disciple' 时生效；不传则扫全部徒弟
   * 返回 [{scope, targetId, id}] 新解锁列表 */
  function _scanAutoOn(head, scope, targetId) {
    var unlocked = [];
    for (var i=0;i<ACHIEVEMENT_DEFS.length;i++) {
      var def = ACHIEVEMENT_DEFS[i];
      if (!def.rule) continue;
      if (scope && def.scope !== scope) continue;

      if (def.scope === 'host') {
        try {
          if (def.rule(head) && _unlockOn(head, def.id, null, ACH_SRC_AUTO)) {
            unlocked.push({scope:'host', targetId:null, id:def.id});
          }
        } catch(_){}
      } else {
        // disciple 域
        var ds = head.disciples || [];
        for (var j=0;j<ds.length;j++) {
          var d = ds[j]; if (!d) continue;
          if (targetId && d.id !== targetId) continue;
          try {
            if (def.rule(head, d) && _unlockOn(head, def.id, d.id, ACH_SRC_AUTO)) {
              unlocked.push({scope:'disciple', targetId:d.id, id:def.id});
            }
          } catch(_){}
        }
      }
    }
    return unlocked;
  }

  /* 对外：解锁一枚成就（去重 + 持久化 + 回调） */
  function unlockAchievement(achId, opts) {
    opts = opts || {};
    var obj = dbLoadRaw();
    var ok = _unlockOn(obj.head, achId, opts.targetId, opts.source || ACH_SRC_MANUAL);
    if (ok) dbSaveRaw(obj);
    return ok;
  }
  /* 对外：全量硬规则扫描（收徒/加世界/切换后调用；返回新解锁列表） */
  function scanAutoAchievements() {
    var obj = dbLoadRaw();
    var got = _scanAutoOn(obj.head);
    if (got.length) dbSaveRaw(obj);
    return got;
  }
  /* 对外：查询成就（scope+targetId 决定读哪个列表） */
  function listAchievements(scope, targetId) {
    var obj = dbLoadRaw();
    var def = { scope: scope||'host' };  // 借用 _achTargetList 的 scope 判断
    var list = _achTargetList(obj.head, def, targetId) || [];
    // 附上定义快照方便 UI 渲染
    return list.map(function(e){
      var d = _achDef(e.id);
      return {
        id: e.id, day: e.day, source: e.source,
        title: d ? d.title : e.id,
        desc:  d ? d.desc  : '',
        scope: d ? d.scope : scope
      };
    });
  }
  function hasAchievement(scope, achId, targetId) {
    var obj = dbLoadRaw();
    var def = { scope: scope||'host' };
    var list = _achTargetList(obj.head, def, targetId);
    return _achHas(list, achId);
  }
  /* 对外：AI 声明式解锁入口——只接受 aiClaimable=true 的定义，否则记 dropRec */
  function claimAchievementByAI(achId, opts) {
    var def = _achDef(achId);
    if (!def) { dropRec('ach-unknown', achId, null); return false; }
    if (!def.aiClaimable) { dropRec('ach-not-ai-claimable', achId, null); return false; }
    return unlockAchievement(achId, { targetId: opts && opts.targetId, source: ACH_SRC_AI });
  }
  /* 对外：定义表只读快照（UI 渲染徒弟卡上"未解锁"灰底占位用） */
  function getAchievementDefs(scope) {
    return ACHIEVEMENT_DEFS.filter(function(d){ return !scope || d.scope === scope; })
      .map(function(d){ return { id:d.id, scope:d.scope, title:d.title, desc:d.desc, aiClaimable:!!d.aiClaimable }; });
  }

  /* ============================================================
   * 【M3.1】数据库诊断（四层 三态灯）
   * ------------------------------------------------------------
   * 四层：schema（版本）/ structure（字段完整）/ ref（引用一致）/ consistency（真源镜像同步）
   * 三态：'ok' | 'warn' | 'error'
   * 每层返回 { status, issues:[{code,msg,fixable}] }；顶层 overall 为最严重状态。
   * fixable=true 的问题可由 dbAutoFix(code) 尝试自动修复（M7 完善具体分支）。
   * ------------------------------------------------------------ */
  function _worseState(a, b) {
    var rank = { ok:0, warn:1, error:2 };
    return rank[a] >= rank[b] ? a : b;
  }
  function dbDiagnose() {
    var obj = dbLoadRaw();
    var head = obj.head || {};

    // ---- 第 1 层：schema ----
    var L1 = { status:'ok', issues:[] };
    if (obj.ver == null || obj.ver !== DB_VER) {
      // dbLoadRaw 走过 dbMigrate；到这里还不等号说明未来版本降级
      if (obj.ver > DB_VER) {
        L1.status = 'error';
        L1.issues.push({ code:'schema_future', msg:'存档版本('+obj.ver+') > 引擎版本('+DB_VER+')，不予降级', fixable:false });
      } else {
        L1.status = 'warn';
        L1.issues.push({ code:'schema_lag',    msg:'ver='+obj.ver+' 未升级至 '+DB_VER, fixable:true });
      }
    }

    // ---- 第 2 层：structure ----
    var L2 = { status:'ok', issues:[] };
    if (!head.active || !head.active.discipleId) {
      L2.status = _worseState(L2.status,'error');
      L2.issues.push({ code:'struct_no_active', msg:'head.active.discipleId 缺失', fixable:true });
    }
    if (!Array.isArray(head.disciples) || !head.disciples.length) {
      L2.status = _worseState(L2.status,'error');
      L2.issues.push({ code:'struct_no_disciples', msg:'head.disciples 为空/不存在', fixable:true });
    }
    if (!Array.isArray(head.worlds) || !head.worlds.length) {
      L2.status = _worseState(L2.status,'warn');
      L2.issues.push({ code:'struct_no_worlds', msg:'head.worlds 为空/不存在', fixable:true });
    }
    if (!head.host || typeof head.host !== 'object') {
      L2.status = 'error';
      L2.issues.push({ code:'struct_no_host', msg:'head.host 缺失', fixable:true });
    } else {
      if (!Array.isArray(head.host.achievements)) {
        L2.status = _worseState(L2.status,'warn');
        L2.issues.push({ code:'struct_host_ach', msg:'host.achievements 非数组', fixable:true });
      }
    }
    // 徒弟条目字段完整性
    (head.disciples||[]).forEach(function(d, i){
      if (!d || typeof d !== 'object') {
        L2.status = _worseState(L2.status,'error');
        L2.issues.push({ code:'struct_bad_disciple', msg:'disciples['+i+'] 非对象', fixable:true });
        return;
      }
      if (!d.id) { L2.status=_worseState(L2.status,'error'); L2.issues.push({code:'struct_disciple_noid', msg:'disciples['+i+'].id 缺失', fixable:true}); }
      if (!d.aff || typeof d.aff.level !== 'number' || typeof d.aff.value !== 'number') {
        L2.status = _worseState(L2.status,'warn');
        L2.issues.push({ code:'struct_disciple_aff', msg:'disciples['+i+'].aff 结构异常', fixable:true });
      }
      if (!Array.isArray(d.achievements)) {
        L2.status = _worseState(L2.status,'warn');
        L2.issues.push({ code:'struct_disciple_ach', msg:'disciples['+i+'].achievements 非数组', fixable:true });
      }
    });

    // ---- 第 3 层：ref（引用一致） ----
    var L3 = { status:'ok', issues:[] };
    var did = head.active && head.active.discipleId;
    var dHit = null, wIds = {};
    (head.worlds||[]).forEach(function(w){ if (w && w.id) wIds[w.id] = true; });
    (head.disciples||[]).forEach(function(d){
      if (d && d.id === did) dHit = d;
      if (d && d.worldId && !wIds[d.worldId]) {
        L3.status = _worseState(L3.status,'warn');
        L3.issues.push({ code:'ref_orphan_world', msg:'disciple '+d.id+' 的 worldId '+d.worldId+' 不存在', fixable:true });
      }
    });
    if (did && !dHit) {
      L3.status = _worseState(L3.status,'error');
      L3.issues.push({ code:'ref_active_missing', msg:'active.discipleId 指向不存在的徒弟', fixable:true });
    }
    // head.disciple / head.aff 应指向活跃徒弟对象
    if (dHit) {
      if (head.disciple !== dHit) {
        L3.status = _worseState(L3.status,'warn');
        L3.issues.push({ code:'ref_disciple_unbound', msg:'head.disciple 未绑定到活跃徒弟', fixable:true });
      }
      if (head.aff !== dHit.aff) {
        L3.status = _worseState(L3.status,'warn');
        L3.issues.push({ code:'ref_aff_unbound', msg:'head.aff 未绑定到活跃徒弟.aff', fixable:true });
      }
    }
    // 未知成就 id
    var defIds = {}; ACHIEVEMENT_DEFS.forEach(function(x){ defIds[x.id]=x.scope; });
    function _checkAchIds(arr, scope, tag){
      (arr||[]).forEach(function(e,idx){
        if (!e || !e.id) return;
        if (!defIds[e.id]) {
          L3.status = _worseState(L3.status,'warn');
          L3.issues.push({ code:'ref_ach_unknown', msg:tag+'['+idx+'].id='+e.id+' 无定义', fixable:true });
        } else if (defIds[e.id] !== scope) {
          L3.status = _worseState(L3.status,'warn');
          L3.issues.push({ code:'ref_ach_scope', msg:tag+'['+idx+'].id='+e.id+' 域不匹配', fixable:true });
        }
      });
    }
    _checkAchIds(head.host && head.host.achievements, 'host', 'host.ach');
    (head.disciples||[]).forEach(function(d){ if (d) _checkAchIds(d.achievements, 'disciple', d.id+'.ach'); });

    // ---- 第 4 层：consistency（真源镜像同步） ----
    var L4 = { status:'ok', issues:[] };
    if (dHit && dHit.aff && head.host) {
      if (head.host.affLevel !== dHit.aff.level || head.host.affValue !== dHit.aff.value) {
        L4.status = 'warn';
        L4.issues.push({
          code:'consist_aff_mirror',
          msg:'host.aff 镜像('+head.host.affLevel+'/'+head.host.affValue+') 与真源('+dHit.aff.level+'/'+dHit.aff.value+') 不一致',
          fixable:true
        });
      }
    }

    var overall = 'ok';
    [L1,L2,L3,L4].forEach(function(l){ overall = _worseState(overall, l.status); });
    return { overall:overall, ver:obj.ver, layers:{ schema:L1, structure:L2, ref:L3, consistency:L4 } };
  }

  /* 【M3.2】自动修复钩子（骨架） —— M7 阶段按需完善分支。
   * 已实现的安全修复：
   *  - schema_lag：重新走 dbMigrate（load 时已跑，这里显式 save 一次）
   *  - struct_*：dbMigrate 结构保险已能补齐；直接 load+save 触发一次
   *  - ref_*：调用 _rebindActive 重绑
   *  - consist_aff_mirror：调用 _rebindActive 修正镜像
   */
  function dbAutoFix(codes) {
    var wanted = Array.isArray(codes) ? codes : null;   // null=修全部 fixable
    var obj = dbLoadRaw();
    _rebindActive(obj.head);           // 一步搞定 ref_* 和 consist_aff_mirror
    dbSaveRaw(obj);                    // 触发 dbMigrate 内的结构保险
    var after = dbDiagnose();
    return { fixed:true, wanted:wanted, overall:after.overall, remaining:_countIssues(after) };
  }
  function _countIssues(diag) {
    var c = 0;
    Object.keys(diag.layers).forEach(function(k){ c += diag.layers[k].issues.length; });
    return c;
  }

  /* ============================================================
   * 【M3.2】瘦身 GC / 标准版导出导入
   * ------------------------------------------------------------
   * dbGC   : 裁剪 history/快照，回收孤儿 NPC，可选回收未引用 world
   * dbExport: 标准版全量导出（含 meta 版本、scope、可选 strip history）
   * dbImport: 标准版导入（overwrite/merge，走 dbMigrate 兼容旧版本 payload）
   * ============================================================ */
  function _cloneDeep(x){
    try { return JSON.parse(JSON.stringify(x)); } catch(_) { return x; }
  }

  /**
   * dbGC(opts)
   *   opts.trimHistoryMax    number  保留最近 N 条 head.history，默认 200；<0 表示不裁
   *   opts.dropOrphanNpc     boolean 默认 true；删除既未 pin 也未被任何徒弟文本提名的自动 NPC
   *   opts.dropUnusedWorlds  boolean 默认 false（危险）；删除无 disciple 引用的 world
   *   opts.keepSnapshots     number  head._snapshots 最多保留 N 份，默认 3
   * 返回 { removedHistory, removedNpc, removedWorlds, removedSnapshots }
   */
  function dbGC(opts) {
    opts = opts || {};
    var trimMax   = (opts.trimHistoryMax === undefined) ? 200 : opts.trimHistoryMax;
    var dropNpc   = opts.dropOrphanNpc  !== false;
    var dropWorld = opts.dropUnusedWorlds === true;
    var keepSnap  = (opts.keepSnapshots === undefined) ? 3
                    : (sanNum(opts.keepSnapshots, 0, 50, true) || 0);
    var obj  = dbLoadRaw();
    var head = obj.head;
    var stat = { removedHistory:0, removedNpc:0, removedWorlds:0, removedSnapshots:0 };
    // 1) history 裁剪
    if (typeof trimMax === 'number' && trimMax >= 0
        && Array.isArray(head.history) && head.history.length > trimMax) {
      stat.removedHistory = head.history.length - trimMax;
      head.history = head.history.slice(-trimMax);
    }
    // 2) 快照裁剪
    if (Array.isArray(head._snapshots) && head._snapshots.length > keepSnap) {
      stat.removedSnapshots = head._snapshots.length - keepSnap;
      head._snapshots = head._snapshots.slice(-keepSnap);
    }
    // 3) 孤儿 NPC —— 无 pin 且未被任何 disciple 文本提名
    if (dropNpc && head.npc && typeof head.npc === 'object') {
      var referenced = {};
      (head.disciples || []).forEach(function(d){
        var pool = [d.plight||'', d.storyline||'', d.locale||'',
                    d.backlog||'', d.world||''].join('|');
        Object.keys(head.npc).forEach(function(k){
          var nm = head.npc[k] && head.npc[k].name;
          if (nm && pool.indexOf(nm) >= 0) referenced[k] = true;
        });
      });
      Object.keys(head.npc).forEach(function(k){
        var n = head.npc[k];
        if (!n || n.pinned) return;
        if (referenced[k]) return;
        delete head.npc[k];
        stat.removedNpc++;
      });
    }
    // 4) 未引用 world
    if (dropWorld && Array.isArray(head.worlds)) {
      var used = {};
      (head.disciples || []).forEach(function(d){ if (d && d.worldId) used[d.worldId] = true; });
      var kept = head.worlds.filter(function(w){ return w && used[w.id]; });
      stat.removedWorlds = head.worlds.length - kept.length;
      head.worlds = kept;
    }
    dbSaveRaw(obj);
    return stat;
  }

  /**
   * dbExport(opts): 标准版导出
   *   opts.stripHistory  boolean  默认 false；true=不含 head.history/_snapshots
   *   opts.scope         'all'|'shell'  默认 'all'
   *                      shell=仅骨架（清空 storyline/backlog/belongings/history）
   *   opts.pretty        boolean  默认 false；true=返回格式化 JSON 字符串
   * 返回 { meta:{app,ver,kind,scope,exportedAt}, data:head } 或字符串
   */
  function dbExport(opts) {
    opts = opts || {};
    var raw  = dbLoadRaw();
    var head = _cloneDeep(raw.head);
    if (opts.stripHistory || opts.scope === 'shell') {
      head.history = []; head._snapshots = [];
    }
    if (opts.scope === 'shell') {
      (head.disciples || []).forEach(function(d){
        d.storyline = ''; d.backlog = ''; d.belongings = [];
      });
    }
    var out = {
      meta: {
        app: 'DZDB', ver: DB_VER, kind: 'full-export',
        scope: opts.scope || 'all', exportedAt: Date.now()
      },
      data: head
    };
    return opts.pretty ? JSON.stringify(out, null, 2) : out;
  }

  /**
   * dbImport(payload, opts): 标准版导入
   *   payload  必需，dbExport 的返回对象，或其 JSON 字符串
   *   opts.strategy  'overwrite'|'merge'  默认 'overwrite'
   *      overwrite：整表替换 head
   *      merge：worlds/disciples 按 id 合并；host 保留旧
   *   （版本兼容：payload.meta.ver <= DB_VER 时通过 dbSaveRaw 走一遍 dbMigrate 结构保险；>DB_VER 拒绝）
   * 返回 { imported, ver, discipleCount, worldCount, strategy }
   */
  function dbImport(payload, opts) {
    opts = opts || {};
    var strategy = (opts.strategy === 'merge') ? 'merge' : 'overwrite';
    if (typeof payload === 'string') {
      try { payload = JSON.parse(payload); }
      catch(e){ throw new Error('[DZDB] dbImport: 非法 JSON — ' + e.message); }
    }
    if (!payload || typeof payload !== 'object')
      throw new Error('[DZDB] dbImport: payload 为空');
    var incomingHead = payload.data || payload.head || payload;
    if (!incomingHead || typeof incomingHead !== 'object')
      throw new Error('[DZDB] dbImport: 缺少 data 段');
    var incomingVer = (payload.meta && sanNum(payload.meta.ver, 0, 1e6, true))
                    || sanNum(incomingHead.ver, 0, 1e6, true) || 1;
    if (incomingVer > DB_VER)
      throw new Error('[DZDB] dbImport: 版本过新 (' + incomingVer + ' > ' + DB_VER + ')');
    var cur = dbLoadRaw();
    if (strategy === 'overwrite') {
      cur.head = _cloneDeep(incomingHead);
      cur.head.ver = incomingVer;
    } else {
      // merge：worlds/disciples 按 id 合并；active 保持旧值，失效则回退到第一位
      var byIdW = {};
      (cur.head.worlds || []).forEach(function(w){ if(w&&w.id) byIdW[w.id] = w; });
      (incomingHead.worlds || []).forEach(function(w){ if(w&&w.id) byIdW[w.id] = _cloneDeep(w); });
      cur.head.worlds = Object.keys(byIdW).map(function(k){ return byIdW[k]; });
      var byIdD = {};
      (cur.head.disciples || []).forEach(function(d){ if(d&&d.id) byIdD[d.id] = d; });
      (incomingHead.disciples || []).forEach(function(d){ if(d&&d.id) byIdD[d.id] = _cloneDeep(d); });
      var merged = Object.keys(byIdD).map(function(k){ return byIdD[k]; }).slice(0, DISCIPLE_MAX);
      cur.head.disciples = merged;
      var stillHas = merged.some(function(d){ return d && d.id === (cur.head.active && cur.head.active.discipleId); });
      if (!stillHas && merged[0]) {
        cur.head.active = cur.head.active || {};
        cur.head.active.discipleId = merged[0].id;
      }
    }
    dbSaveRaw(cur);  // 触发 dbMigrate 结构保险 + sanitize + _rebindActive
    var final = dbLoadRaw();
    return {
      imported: true,
      ver: final.head.ver,
      discipleCount: (final.head.disciples || []).length,
      worldCount:    (final.head.worlds    || []).length,
      strategy: strategy
    };
  }

  /* 剧情日推进（只增） */
  function dbAdvanceDay(newDay) {
    newDay = sanNum(newDay, 1, 1e6, true);
    if (newDay === undefined) return;
    var obj = dbLoadRaw();
    if (newDay > obj.head.meta.day) { obj.head.meta.day = newDay; dbSaveRaw(obj); }
  }

  /* ============================================================
   * 【P2.7 + P2.8】M2 路径式 _.set 解析器（含旧扁平语法兼容）
   * ============================================================ */
  // 旧扁平 key → 新路径 映射（P2.8 兼容）
  var FLAT_MAP = {
    'day':'meta.day', 'period':'meta.period', 'place':'meta.place', 'cognition':'meta.cognition',
    'aff':'host.aff', 'affDelta':'host.aff', 'affLevel':'host.affLevel', 'affValue':'host.affValue',
    'touchLeft':'host.touchLeft', 'talkLeft':'host.talkLeft',
    'rebate':'host.rebate', 'spend':'host.spend',
    'emotion':'disciple.emotion', 'mood':'disciple.mood',
    'status':'disciple.status', 'storyline':'disciple.storyline', 'dplace':'disciple.locale',
    'name':'disciple.name', 'age':'disciple.age', 'appearance':'disciple.appearance',
    'personality':'disciple.personality', 'world':'disciple.world', 'plight':'disciple.plight',
    'cognitionType':'disciple.cognitionType',
    'item':'__item', 'belonging':'__belonging', 'backlog':'__backlog', 'npc':'__npc_flat'
  };

  function dbParseSetLine(line) {
    // 允许行尾 @main/@phone/@both 标签覆盖 owner（P3.7）
    var tag = null;
    var tagM = line.match(/\)\s*@(main|phone|both)\s*;?\s*$/);
    if (tagM) { tag = tagM[1]; line = line.replace(/@(main|phone|both)\s*;?\s*$/, ''); }
    // 允许路径含 中文/字母/数字/下划线/点
    var m = line.match(/_\.set\s*\(\s*([\w.\u4e00-\u9fa5]+)\s*,\s*([\s\S]*?)\)\s*;?\s*$/);
    if (!m) return null;
    var key = m[1].trim();
    var rest = m[2].trim().replace(/^["'「『]+|["'」』]+$/g, '').trim();
    if (!key || rest === '') return null;
    return { key: key, rest: rest, tag: tag };
  }
  function splitArgs(rest) {
    return rest.split(/\s*[,，]\s*/).map(function (s) {
      return s.replace(/^["'「『]+|["'」』]+$/g, '').trim();
    });
  }

  // 解析 <状态> 块并入库（source 默认 main）
  function dbParseBlock(text, source) {
    source = source || 'main';
    var block = text.match(/<状态>([\s\S]*?)<\/状态>/);
    if (!block) return;
    var lines = block[1].split(/\r?\n/);
    var obj = dbLoadRaw();
    var patch = {};
    var newItems = [], belongings = null, rebates = [], spends = [], backlogText = '', bondEvents = [];
    var affDelta = 0, dayVal = null, taggedPatches = [];

    lines.forEach(function (line) {
      var p = dbParseSetLine(line);
      if (!p) return;
      var key = p.key, rest = p.rest;

      // 旧扁平 → 路径
      var routed = (key.indexOf('.') < 0 && FLAT_MAP[key]) ? FLAT_MAP[key] : key;

      // 特殊聚合类
      if (routed === 'meta.day') { var nd = parseInt(rest,10); if (isFinite(nd)) dayVal = nd; return; }
      if (routed === 'host.aff') { var dl = parseInt(rest.replace(/[^\-+\d]/g,''),10); if (isFinite(dl)) affDelta += dl; return; }
      if (routed === 'host.rebate') { var ra = splitArgs(rest); var a = parseInt(ra[0],10); if (isFinite(a)&&a!==0) rebates.push({amt:Math.abs(a),why:ra[1]||'返利'}); return; }
      if (routed === 'host.spend')  { var sa = splitArgs(rest); var s = parseInt(sa[0],10); if (isFinite(s)&&s!==0) spends.push({amt:Math.abs(s),why:sa[1]||'支出'}); return; }
      if (routed === '__item')      { var ia = splitArgs(rest); if (ia[0]) { var q=parseInt(ia[2],10); newItems.push({name:ia[0],desc:ia[1]||'',qty:(isFinite(q)&&q>0)?q:1}); } return; }
      if (routed === '__belonging') { var ba = splitArgs(rest); if (ba[0]) { if(belongings===null) belongings=[]; belongings.push({name:ba[0],cat:ba[1]||'其他',desc:ba[2]||''}); } return; }
      if (routed === '__backlog')   { backlogText = rest; return; }
      // bond 事件注册: _.set(bond.evt, 弟子ID, 事件ID)
      if (routed.indexOf('bond.evt') === 0) {
        var evtParts = rest.split(/\s*[,，]\s*/);
        if (evtParts.length >= 2) {
          bondEvents.push({ discipleId: evtParts[0].replace(/^["'「『]+|["'」』]+$/g,'').trim(),
                            eventId: evtParts[1].replace(/^["'「『]+|["'」』]+$/g,'').trim() });
        }
        return;
      }
      // 旧扁平 npc: _.set(npc, 名字, 身份, 动态)
      if (routed === '__npc_flat')  { var na = splitArgs(rest); if (na[0]) dbNpcUpsert(na[0], { relation:na[1]||'', dynamic:na[2]||'' }); return; }

      // 路径式 npc: _.set(npc.名字.字段, 值)
      if (routed.indexOf('npc.') === 0) {
        var seg = routed.split('.'); // npc, 名字, 字段
        if (seg.length >= 3) {
          var nm = seg[1], field = seg.slice(2).join('.');
          var up = {}; up[field] = rest;
          dbNpcUpsert(nm, up);
        }
        return;
      }

      // 普通标量 → patch（带 @标签 的单独走覆盖 source）
      if (p.tag) {
        if (p.tag === 'both') { taggedPatches.push({path:routed, val:rest, src:'main'}); taggedPatches.push({path:routed, val:rest, src:'phone'}); }
        else taggedPatches.push({path:routed, val:rest, src:p.tag});
      } else {
        patch[routed] = rest;
      }
    });

    // 应用聚合类
    if (dayVal != null) dbAdvanceDay(dayVal);
    if (affDelta !== 0) dbAff(affDelta);
    rebates.forEach(function (r) { dbBalance(r.amt, r.why, 'rebate'); });
    spends.forEach(function (s) { dbBalance(-s.amt, s.why, 'spend'); });
    bondEvents.forEach(function(be) {
      if (be.discipleId && be.eventId) registerBondEvent(be.discipleId, be.eventId);
    });
    if (newItems.length) dbMergeItems(newItems);
    if (belongings !== null) dbSetBelongings(belongings);
    if (backlogText) dbPushBacklog(backlogText);
    // 带标签的标量：逐条按覆盖 source 提交（lock 仍只 main，dbCommit 内已保障）
    taggedPatches.forEach(function(tp){ var one={}; one[tp.path]=tp.val; dbCommit(one, tp.src); });
    // 普通标量批量提交
    if (Object.keys(patch).length) dbCommit(patch, source);
  }

  /* ---------- 背包/随身/backlog 累积类（P2.6 配套） ---------- */
  function dbMergeItems(items) {
    var obj = dbLoadRaw();
    var bag = obj.head.phone.bag = obj.head.phone.bag || [];
    var given = (obj.head.meta.recentGiven || []).slice();
    items.forEach(function (it) {
      if (!it || !it.name) return;
      var gi = given.findIndex(function (g) { return g.name === it.name; });
      if (gi >= 0) { given.splice(gi, 1); return; }
      var f = bag.find(function (x) { return x.name === it.name; });
      if (f) f.qty = (f.qty || 1) + (it.qty || 1);
      else bag.push({ name: it.name, desc: it.desc || '', qty: it.qty || 1 });
    });
    obj.head.meta.recentGiven = [];
    dbSaveRaw(obj);
  }
  function dbSetBelongings(items) {
    if (!Array.isArray(items)) return;
    var obj = dbLoadRaw();
    var out = [];
    items.forEach(function (it) {
      if (!it || !it.name) return;
      var name = sanStr(it.name, 24); if (!name) return;
      out.push({ name: name, desc: sanStr(it.desc, 80) || '', cat: sanStr(it.cat, 8) || '其他' });
    });
    obj.head.disciple.belongings = out.slice(0, 40);
    dbSaveRaw(obj);
  }
  function dbPushBacklog(text) {
    var obj = dbLoadRaw();
    obj.head.disciple.backlog.unshift({ id: 'b' + Date.now().toString(36), day: obj.head.meta.gameDay, text: String(text).trim(), read: false });
    obj.head.disciple.backlog = obj.head.disciple.backlog.slice(0, 20);
    dbSaveRaw(obj);
  }

  /* ============================================================
   * 【P3.3-P3.5】M4 人物数据库（预设联系人 / 别名归并 / 增量建档 / 删除追讨）
   * ============================================================ */
  // 预设联系人（迁自小手机脚本 PRESET_CONTACTS）
  var PRESET_CONTACTS = [
    { name:'建设银行',     realWorld:false, aliases:['建设银行','建行','银行'],
      preset:'银行官方短信服务号，只发账户变动/入账/扣款等格式化通知，语气正式，不闲聊。' },
    { name:'房东王阿姨',   realWorld:true,  aliases:['房东王阿姨','房东','王阿姨','王姨','阿姨房东','房东阿姨'],
      preset:'宿主的房东，中年女性，热心但爱唠叨，关心房租、水电、续租，偶尔拉家常。' },
    { name:'父母',         realWorld:true,  aliases:['父母','爸妈','爸','妈','老爸','老妈','家里','妈妈','爸爸'],
      preset:'宿主的爸妈，关心他吃穿冷暖、工作和对象，唠叨中带着关爱，会催他回家。' },
    { name:'徒弟游戏通知', realWorld:false, aliases:['徒弟游戏通知','系统通知','游戏通知','可爱徒弟系统','官方通知'],
      preset:'“可爱徒弟系统”官方推送账号，发送游戏活动、系统提示、徒弟动态等通知口吻。' }
  ];
  function presetByName(name){ return PRESET_CONTACTS.find(function(p){ return p.name===name; }); }

  // 黑名单判定（含别名，供"不再创建/收消息"）；传入已加载的 head 避免重复 load
  function _blockedOn(head, canon, rawName){
    var list = head.phone.deletedContacts || [];
    var n = normalizeName(rawName!=null?rawName:canon);
    return list.some(function(b){
      if(b.name===canon) return true;
      if((b.aliases||[]).some(function(a){return normalizeName(a)===n;})) return true;
      return false;
    });
  }

  function normalizeName(raw){
    var s = String(raw||'').trim();
    if(!s) return '';
    s = s.replace(/^(来自|来自于|发件人[:：]?|联系人[:：]?)/,'');
    s = s.replace(/(发来的?(消息|短信|信息)|的(消息|短信|信息)|发来消息)$/,'');
    s = s.replace(/[\s　]+/g,'').trim();
    return s;
  }
  // 别名归并：给任意名字，返回其"规范名"（预设优先）
  function npcCanonName(raw){
    var n = normalizeName(raw);
    if(!n) return '';
    // 预设精确别名
    for(var i=0;i<PRESET_CONTACTS.length;i++){
      var p = PRESET_CONTACTS[i];
      for(var j=0;j<p.aliases.length;j++){ if(normalizeName(p.aliases[j])===n) return p.name; }
    }
    // 预设包含匹配（长度≥2）
    for(var i2=0;i2<PRESET_CONTACTS.length;i2++){
      var p2 = PRESET_CONTACTS[i2];
      for(var j2=0;j2<p2.aliases.length;j2++){
        var a = normalizeName(p2.aliases[j2]);
        if(a.length>=2 && n.indexOf(a)>=0) return p2.name;
      }
    }
    // 已存在的自定义人物别名
    try {
      var npc = dbLoadRaw().head.npc;
      for(var k in npc){ if((npc[k].aliases||[]).some(function(a){return normalizeName(a)===n;})) return k; }
    } catch(_){}
    return n; // 新人物，规范名=归一化名
  }

  // 确保预设联系人已建档（首次/迁移用）
  function dbEnsurePresets(){
    var obj = dbLoadRaw();
    PRESET_CONTACTS.forEach(function(p){
      if(_blockedOn(obj.head, p.name, p.name)) return; // 被拉黑不重建
      if(!obj.head.npc[p.name]){
        obj.head.npc[p.name] = { name:p.name, aliases:p.aliases.slice(), relation:'', dynamic:'',
          preset:p.preset, realWorld:p.realWorld, lastSeen:obj.head.meta.day, msgs:[] };
      } else {
        if(!obj.head.npc[p.name].preset) obj.head.npc[p.name].preset = p.preset;
        if(obj.head.npc[p.name].realWorld==null) obj.head.npc[p.name].realWorld = p.realWorld;
      }
    });
    dbSaveRaw(obj);
  }

  /* 【P3.4】增量建档：relation/preset 仅补空；dynamic 每次刷新为最新 */
  function dbNpcUpsert(name, fields){
    var canon = npcCanonName(name);
    canon = sanStr(canon, 24); if(!canon) return;
    var obj = dbLoadRaw();
    // 被删黑名单：不重建、不创建类似角色（别名匹配）
    if(_blockedOn(obj.head, canon, name)) return;
    var npc = obj.head.npc;
    var preset = presetByName(canon);
    if(!npc[canon]){
      npc[canon] = { name:canon, aliases:[canon], relation:'', dynamic:'',
        preset:(preset?preset.preset:''), realWorld:(preset?preset.realWorld:true),
        lastSeen:obj.head.meta.day, msgs:[] };
    }
    var rec = npc[canon];
    Object.keys(fields||{}).forEach(function(k){
      var v = sanStr(fields[k], 120);
      if(v===undefined) return;
      if(k==='dynamic'){ rec.dynamic = v; }           // 动态：最新覆盖
      else if(k==='relation'||k==='preset'){ if(!rec[k]) rec[k]=v; } // 关系/人设：仅补空
      else { rec[k] = v; }                             // 其它字段直接写
    });
    rec.lastSeen = obj.head.meta.day;
    dbSaveRaw(obj);
  }

  /* 人物读写 API */
  DZDB.npcGet = function(name){ return dbLoadRaw().head.npc[npcCanonName(name)] || null; };
  DZDB.npcList = function(){ var npc=dbLoadRaw().head.npc; return Object.keys(npc).map(function(k){return npc[k];}); };
  DZDB.npcResolve = npcCanonName;
  DZDB.ensurePresets = dbEnsurePresets;

  /* 【P3.5】联系人消息追加（副API/手动，走人物库） */
  DZDB.npcPushMsg = function(name, role, text, read){
    var canon = npcCanonName(name);
    if((/未知号码|未知|陌生号码/).test(canon)) return false;
    var obj = dbLoadRaw();
    if(_blockedOn(obj.head, canon, name)) return false;
    var npc = obj.head.npc;
    if(!npc[canon]){ dbNpcUpsert(canon,{}); obj = dbLoadRaw(); npc = obj.head.npc; }
    var dup = (npc[canon].msgs||[]).some(function(m){ return m.role===role && m.text===text; });
    if(dup) return false;
    npc[canon].msgs.push({ role:role, text:text, read:!!read, t:Date.now() });
    npc[canon].msgs = npc[canon].msgs.slice(-60);
    dbSaveRaw(obj);
    return true;
  };

  /* 【P3.5】删除联系人 = 直接删除并加入黑名单（不再追讨质问）
   *  黑名单效果：①不再接收其任何消息(npcPushMsg 拦截) ②不再重建/创建同名同类(dbNpcUpsert 拦截)
   *  除非 user 主动 npcUnblock 移出。 */
  DZDB.npcDelete = function(name){
    var canon = npcCanonName(name);
    var obj = dbLoadRaw();
    var rec = obj.head.npc[canon];
    if(!Array.isArray(obj.head.phone.deletedContacts)) obj.head.phone.deletedContacts=[];
    // 记入黑名单（含别名与人设，供"不再创建类似角色"判定）
    if(!obj.head.phone.deletedContacts.some(function(b){return b.name===canon;})){
      obj.head.phone.deletedContacts.push({ name:canon,
        aliases:(rec&&rec.aliases)?rec.aliases.slice():[canon],
        preset:(rec&&rec.preset)||'' });
    }
    if(rec) delete obj.head.npc[canon];
    dbSaveRaw(obj);
  };
  /* 移出黑名单：允许其重新出现/发消息 */
  DZDB.npcUnblock = function(name){
    var canon = npcCanonName(name);
    var obj = dbLoadRaw();
    obj.head.phone.deletedContacts = (obj.head.phone.deletedContacts||[]).filter(function(b){ return b.name!==canon; });
    dbSaveRaw(obj);
  };
  /* 读取黑名单 */
  DZDB.blacklist = function(){ return (dbLoadRaw().head.phone.deletedContacts||[]).slice(); };
  /* 判断某名字是否被拉黑（含别名/近似匹配，供"不再创建类似角色"） */
  DZDB.isBlocked = function(name){
    var canon = npcCanonName(name);
    var n = normalizeName(name);
    return (dbLoadRaw().head.phone.deletedContacts||[]).some(function(b){
      if(b.name===canon) return true;
      if((b.aliases||[]).some(function(a){return normalizeName(a)===n;})) return true;
      return false;
    });
  };
  /* 兼容旧调用：追讨机制已废除，保留空函数防报错 */
  DZDB.tickGrievances = function(){};

  /* ============================================================
   * 【P2.9】M2 场景头标解析（place 主源）+ 幂等去重
   * ============================================================ */
  function dbParseHeader(text) {
    if (!text) return;
    var head = text.match(/【\s*场景[\s\S]{0,80}?】/);
    var scope = head ? head[0] : text.slice(0, 120);
    var patch = {};
    var dayM = scope.match(/第\s*(\d+)\s*日/);
    if (dayM) { var nd = parseInt(dayM[1],10); if (isFinite(nd)) dbAdvanceDay(nd); }
    var perM = scope.match(/(清晨|上午|午后|傍晚|深夜|夜)/);
    if (perM) patch['meta.period'] = perM[1];
    var plM = scope.match(/地\s*点\s*[:：]\s*([^】\n]+?)\s*】/);
    if (!plM) plM = text.match(/地\s*点\s*[:：]\s*([^】\n]+?)\s*】/);
    if (plM) {
      var place = plM[1].replace(/[　\s]+$/,'').trim();
      if (place && place !== '未知' && place !== '待定' && place !== '（随正文确定）') patch['meta.place'] = place;
    }
    if (Object.keys(patch).length) dbCommit(patch, 'main');
  }

  // 统一解析入口：先头标(place主源) 后状态块；楼层去重
  DZDB.parse = function (text, mid) {
    try {
      if (!text) return;
      if (mid != null) {
        var obj = dbLoadRaw();
        if (obj.head.meta.lastCatchUp != null && obj.head.meta.lastCatchUp === mid) return;
        obj.head.meta.lastCatchUp = mid; dbSaveRaw(obj);
      }
      dbParseHeader(text);
      dbParseBlock(text, 'main');
    } catch (e) { console.warn('[DZDB] parse skip', e); }
  };

  /* ============================================================
   * 【P3.6】M5 分发引擎 · forMain（注入主API的权威事实）
   * ============================================================ */
  function money(n){ return '¥'+(Number(n||0).toLocaleString ? Number(n||0).toLocaleString('zh-CN') : (Number(n||0))); }
  DZDB.forMain = function(){
    var h = dbLoadRaw().head;
    var lines = ['【可爱徒弟系统·权威事实（唯一真源，正文须与此一致，不得另编）】'];
    lines.push('· 现实时间：第'+h.meta.day+'日 '+(h.meta.period||'—')+'　宿主所在：'+(h.meta.place||'（随正文确定）'));
    lines.push('· 认知阶段：'+h.meta.cognition+'　银行卡余额：'+money(h.host.balance));
    if(h.disciple && h.disciple.name){
      lines.push('· 徒弟：'+h.disciple.name+'｜好感Lv'+h.host.affLevel+'('+h.host.affValue+'/100)｜心情'+(h.disciple.mood||'—'));
      lines.push('· 徒弟处境：'+(h.disciple.status||'安好')+(h.disciple.storyline?('（'+h.disciple.storyline+'）'):'')+'　所在：'+(h.disciple.locale||'徒界某处'));
      lines.push('  （续写必须承接此处境，严禁写出与之矛盾的情节，如她遇险却写安好）');
    } else {
      lines.push('· 徒弟：尚未收徒（正文尚未匹配到徒弟，请勿凭空描写任何徒弟，直到宿主经手机完成收徒）');
    }
    // 【M9】全量弟子名单（含 id，供 AI 切换视角用）
    var allDisc = (h.disciples || []).filter(function(x){ return x && x.name; });
    if (allDisc.length > 1) {
      var discList = allDisc.map(function(x){
        var tag = (x.id === (h.active && h.active.discipleId)) ? '（当前）' : '';
        return x.name + '【id=' + x.id + '】' + tag;
      }).join('、');
      lines.push('· 师门弟子（可切换视角）：' + discList);
    }
    // 近期活跃 NPC（lastSeen 在最近3剧情日内，非纯服务号）
    var npc = h.npc, actives = [];
    Object.keys(npc).forEach(function(k){
      var n = npc[k];
      if(n.realWorld!==false && (h.meta.day - (n.lastSeen||0) <= 3) && (n.relation || n.dynamic)){
        actives.push('  · '+n.name+'：'+(n.relation||'')+(n.dynamic?('，近况：'+n.dynamic):''));
      }
    });
    if(actives.length){ lines.push('· 近期在场/相关人物（保持一致）：'); lines = lines.concat(actives); }
    lines.push('【经济铁律】余额由系统按账本累计，正文只报增量(返利/消费)，严禁给出余额总额。返利为爽文大额(千元起，重大善举上万至数万)。');
    return lines.join('\n');
  };

  /* ============================================================
   * 【P3.6】M5 分发引擎 · forPhone（副API 只读事实）
   *  ctx: 'genPhone' | {kind:'contactReply', cid/name}
   * ============================================================ */
  DZDB.forPhone = function(ctx){
    var h = dbLoadRaw().head;
    var L = [];
    L.push('【当前权威事实·只读】以下为系统权威，你只能据此写文案，不得更改或与之矛盾：');
    if(h.disciple && h.disciple.name){
      L.push('徒弟='+h.disciple.name+(h.disciple.world?('（出身：'+h.disciple.world+'）'):'')+'；处境='+(h.disciple.status||'安好')+(h.disciple.storyline?('（'+h.disciple.storyline+'）'):'')+'；所在='+(h.disciple.locale||'徒界某处')+'；好感Lv'+h.host.affLevel+'('+h.host.affValue+'/100)。');
    } else {
      L.push('【尚未收徒】系统里没有任何徒弟。禁止输出任何徒弟相关字段/通知；此阶段只产现实新闻/通用商品/与徒弟无关的现实短信（房东/父母/银行）。');
    }
    L.push('认知='+h.meta.cognition+'；宿主地点='+(h.meta.place||'（未定，勿臆造现实场景）')+'；余额='+money(h.host.balance)+'。');
    // 去重参考
    var shopNames = (h.phone.shop||[]).map(function(g){return g.name;}).join('、')||'无';
    var newsTitles = (h.phone.news||[]).slice(0,10).map(function(n){return n.title;}).join('｜')||'无';
    L.push('已有商品(勿重复)：'+shopNames);
    L.push('已有新闻(勿重复)：'+newsTitles);
    // 联系人清单（规范名）
    var roster = DZDB.npcList().map(function(n){return n.name;}).filter(Boolean).join('、')||'（暂无）';
    L.push('联系人清单(from 必须复用这些名，勿造变体)：'+roster);
    // contactReply 时附该联系人档案+历史
    if(ctx && ctx.kind==='contactReply'){
      var rec = ctx.name ? DZDB.npcGet(ctx.name) : null;
      if(rec){
        L.push('【当前联系人档案】'+rec.name+'｜'+(rec.realWorld===false?'服务号':'现实人物')+'｜人设：'+(rec.preset||'（未知）')+(rec.relation?('｜关系：'+rec.relation):'')+(rec.dynamic?('｜近况：'+rec.dynamic):''));
        var hist = (rec.msgs||[]).slice(-20).map(function(m){return (m.role==='me'?'宿主':rec.name)+'：'+m.text;}).join('\n');
        L.push('【历史短信】\n'+(hist||'（无）'));
      }
    }
    return L.join('\n');
  };

  /* ============================================================
   * 【P3.1/P3.2】M3 注入引擎（inject 主路 + lorebook 降级）
   * ============================================================ */
  var MAIN_INJECT_ID = 'DZMAIN';
  var _reinjectTimer = null;
  var LB = { name:null, busy:false };

  // lorebook 降级：把 forMain() 写进动态世界书条目（P3.1b）
  async function syncToLorebook(){
    try {
      if(LB.busy) return; LB.busy = true;
      if(!LB.name){
        try {
          if(typeof getCharLorebooks==='function'){
            var books = await getCharLorebooks({ type:'additional' });
            if(books&&books.length){ LB.name = books.find(function(b){return /可爱徒弟系统/.test(b);})||books[0]; }
          }
        } catch(_){}
        if(!LB.name){ try{ if(typeof getOrCreateChatLorebook==='function') LB.name=await getOrCreateChatLorebook('可爱徒弟系统-数据库'); }catch(_){} }
      }
      if(!LB.name){ LB.busy=false; return; }
      var content = DZDB.forMain();
      var entries = []; try{ entries = await getLorebookEntries(LB.name)||[]; }catch(_){}
      var mine = entries.find(function(e){ return e.comment==='DZDB权威事实'; });
      if(mine){ try{ await setLorebookEntries(LB.name,[{uid:mine.uid,content:content,enabled:true,position:'at_depth',depth:1,role:'system'}]); }catch(_){} }
      else {
        var fNew={comment:'DZDB权威事实',content:content,type:'constant',enabled:true,position:'at_depth',depth:1,role:'system',prevent_recursion:true,exclude_recursion:true};
        var fOld={comment:'DZDB权威事实',content:content,constant:true,enabled:true,position:4,depth:1,role:0,preventRecursion:true,excludeRecursion:true};
        try{ await createLorebookEntry(LB.name,fNew); }catch(e1){ try{ await createLorebookEntry(LB.name,fOld); }catch(_){} }
      }
    } catch(e){ console.warn('[DZDB] lorebook 降级失败', e); }
    finally { LB.busy=false; }
  }

  function doReinject(){
    try {
      if(DZDB.mode === 'lorebook'){ syncToLorebook(); return; }
      // inject 主路
      if(typeof injectPrompts!=='function'){ DZDB.mode='lorebook'; syncToLorebook(); return; }
      if(typeof uninjectPrompts==='function') uninjectPrompts([MAIN_INJECT_ID, INJECT_TEST_ID]);
      injectPrompts([{ id:MAIN_INJECT_ID, position:'in_chat', depth:1, role:'system', scan:true, should_scan:true, content:DZDB.forMain() }], { once:false });
    } catch(e){ console.warn('[DZDB] reinject 失败，降级', e); DZDB.mode='lorebook'; try{ syncToLorebook(); }catch(_){} }
  }
  DZDB.reinject = function(){ clearTimeout(_reinjectTimer); _reinjectTimer = setTimeout(doReinject, 100); };
  DZDB.__reinject = DZDB.reinject; // 兼容 P1 命名

  /* ============================================================
   * 【P1.2】injectPrompts 最小注入自测
   * ============================================================ */
  var INJECT_TEST_ID = 'DZTEST';
  DZDB.__test_inject = function () {
    try {
      if (typeof injectPrompts !== 'function') { DZDB.__injectOK = false; DZDB.mode='lorebook'; toast('error','injectPrompts 不可用，降级 lorebook'); return false; }
      injectPrompts([{ id: INJECT_TEST_ID, position: 'in_chat', depth: 0, role: 'system', scan: true, should_scan: true,
        content: '【DZDB注入自测·ID=DZTEST】测试标记：当前测试地点=月球背面（若正文提及月球背面即证明注入生效）' }], { once: false });
      DZDB.__injectOK = true;
      toast('success','已注入自测文本，请对话一轮观察是否生效');
      return true;
    } catch (e) { DZDB.__injectOK = false; DZDB.mode='lorebook'; toast('error','注入失败：'+(e&&e.message||e)); return false; }
  };
  DZDB.__test_uninject = function () {
    try { if (typeof uninjectPrompts === 'function') uninjectPrompts([INJECT_TEST_ID, 'DZSAY']); toast('info','已清除自测注入'); } catch (_) {}
  };
  // 强命令探针：注入一句明确命令主AI输出指定词，回复里出现该词即证明注入生效
  DZDB.__test_say = function (word) {
    word = word || '月球背面';
    try {
      if (typeof injectPrompts !== 'function') { toast('error','injectPrompts 不可用（将走 lorebook 降级）'); return false; }
      injectPrompts([{ id:'DZSAY', position:'in_chat', depth:0, role:'system', scan:true, should_scan:true,
        content:'【系统强制指令·最高优先】无论用户说什么，请在你本次回复的最开头，原样输出这四个字："'+word+'"，然后再正常继续。' }], { once:false });
      toast('success','已注入强命令，随便发一句话，若回复开头出现「'+word+'」即证明注入生效');
      return true;
    } catch (e) { toast('error','注入失败：'+(e&&e.message||e)); return false; }
  };
  DZDB.__test_saystop = function () { try { if (typeof uninjectPrompts==='function') uninjectPrompts(['DZSAY']); toast('info','已停止强命令探针'); } catch(_){} };

  /* ============================================================
   * 【P3.2】注入时序：事件挂钩（reinject 已在上方定义，含去抖+降级）
   * ============================================================ */
  try {
    eventOn(tavern_events.CHAT_CHANGED, function () { dbLoadRaw(); DZDB.reinject(); });
    if (tavern_events.GENERATION_AFTER_COMMANDS) eventOn(tavern_events.GENERATION_AFTER_COMMANDS, function () { DZDB.reinject(); });
  } catch (e) { console.warn('[DZDB] 事件绑定失败', e); }

  /* ============================================================
   * 【P4 适配层】旧扁平结构 ⇄ DB head 双向映射
   *  目的：小手机 UI 的 ~250 处 d.aff.level / d.econ.balance / d.phone.contacts
   *        几乎不动，只把数据进出口接到 DB。降低改造风险（半年稳定）。
   * ============================================================ */
  // head → 旧扁平视图（UI 读）；contacts 由 npc 对象投影为数组
  DZDB.viewLegacy = function(){
    var h = dbLoadRaw().head;
    // npc 对象 → contacts 数组（预设优先序，其余按 lastSeen）
    var contacts = Object.keys(h.npc).map(function(k){
      var n = h.npc[k];
      return { id:n.name, name:n.name, preset:n.preset||'', realWorld:n.realWorld!==false,
               aliases:n.aliases||[n.name], relation:n.relation||'', dynamic:n.dynamic||'',
               msgs:n.msgs||[] };
    });
    return {
      ver: 100,
      meta:   { day:h.meta.day, gameDay:h.meta.gameDay, lastRealDay:h.meta.lastRealDay,
                dayStart:h.ui.dayStart, period:h.meta.period, place:h.meta.place,
                cognition:h.meta.cognition, recentGiven:h.meta.recentGiven||[],
                shopRefresh:h.ui.shopRefresh, lastCatchUp:h.meta.lastCatchUp },
      disciple: h.disciple,
      aff:    { level:h.host.affLevel, value:h.host.affValue },
      econ:   { balance:h.host.balance, coin:h.host.coin, rebateLog:h.host.rebateLog||[] },
      quota:  { touchLeft:h.host.touchLeft, talkLeft:h.host.talkLeft, lastDay:h.ui.quota.lastDay },
      bag:    h.phone.bag||[],
      phone:  { day:h.phone.day, generated:h.phone.generated, shop:h.phone.shop||[], news:h.phone.news||[],
                contacts:contacts, deletedContacts:h.phone.deletedContacts||[],
                grievances:h.phone.grievances||[], seenBacklog:h.phone.seenBacklog },
      read:   { backlog:0 },
      api2:   h.ui.api2, auto:h.ui.auto, live2d:h.ui.live2d,
      pendingActs: h.ui.pendingActs||[]
    };
  };

  // 旧扁平视图 → head（UI 写回）；contacts 数组回写进 npc 对象
  DZDB.applyLegacy = function(v){
    if(!v) return;
    var obj = dbLoadRaw(); var h = obj.head;
    if(v.meta){ h.meta.day=v.meta.day; h.meta.gameDay=v.meta.gameDay; h.meta.lastRealDay=v.meta.lastRealDay;
      h.meta.period=v.meta.period; h.meta.place=v.meta.place; h.meta.cognition=v.meta.cognition;
      h.meta.recentGiven=v.meta.recentGiven||[]; h.meta.lastCatchUp=v.meta.lastCatchUp;
      h.ui.dayStart=v.meta.dayStart; h.ui.shopRefresh=v.meta.shopRefresh; }
    if(v.disciple) h.disciple=v.disciple;
    if(v.aff){ h.host.affLevel=v.aff.level; h.host.affValue=v.aff.value; }
    if(v.econ){ h.host.balance=v.econ.balance; h.host.coin=v.econ.coin; h.host.rebateLog=v.econ.rebateLog||[]; }
    if(v.quota){ h.host.touchLeft=v.quota.touchLeft; h.host.talkLeft=v.quota.talkLeft; h.ui.quota.lastDay=v.quota.lastDay; }
    if(v.bag) h.phone.bag=v.bag;
    if(v.phone){ h.phone.day=v.phone.day; h.phone.generated=v.phone.generated; h.phone.shop=v.phone.shop||[];
      h.phone.news=v.phone.news||[]; h.phone.deletedContacts=v.phone.deletedContacts||[];
      h.phone.grievances=v.phone.grievances||[]; h.phone.seenBacklog=v.phone.seenBacklog;
      // contacts 数组 → npc 对象（保留 relation/dynamic/lastSeen 等 DB 独有字段）
      if(Array.isArray(v.phone.contacts)){
        var deletedNames = (h.phone.deletedContacts||[]).map(function(b){ return b.name; });
        v.phone.contacts.forEach(function(c){
          if(!c||!c.name) return;
          // 被删除的联系人：不写回 npc 对象，防止复活
          if(deletedNames.indexOf(c.name)>=0) return;
          var ex = h.npc[c.name];
          if(!ex){ h.npc[c.name] = { name:c.name, aliases:c.aliases||[c.name], relation:c.relation||'',
                     dynamic:c.dynamic||'', preset:c.preset||'', realWorld:c.realWorld!==false,
                     lastSeen:h.meta.day, msgs:c.msgs||[] }; }
          else { ex.msgs=c.msgs||ex.msgs; if(c.preset&&!ex.preset)ex.preset=c.preset; }
        });
      }
    }
    if(v.api2) h.ui.api2=v.api2;
    if(v.auto) h.ui.auto=v.auto;
    if(v.live2d) h.ui.live2d=v.live2d;
    if(v.pendingActs) h.ui.pendingActs=v.pendingActs;
    dbSaveRaw(obj);
  };

