  function sanitizeNumber(val, min, max, isInt){
    var n = Number(val);
    if(!isFinite(n)) return undefined;
    if(isInt) n = Math.round(n);
    if(min!=null) n = Math.max(min, n);
    if(max!=null) n = Math.min(max, n);
    return n;
  }
  function sanitizeStr(val, maxLen){
    if(val==null || typeof val==='object') return undefined;
    var s = String(val).trim();
    if(!s) return undefined;
    if(maxLen && s.length>maxLen) s = s.slice(0, maxLen);
    return s;
  }
  function sanitizePatch(patch){
    var out = {};
    if(!patch || typeof patch!=='object') return out;
    Object.keys(patch).forEach(function(key){
      var v = patch[key];
      if(v==null) return;
      if(NUM_RULE[key]){
        var r = NUM_RULE[key], nv = sanitizeNumber(v, r[0], r[1], r[2]);
        if(nv!==undefined) out[key]=nv;
      } else if(key==='disciple.emotion'){
        var e = sanitizeStr(v, 12);
        if(e && EMOTION_SET.indexOf(e)>=0) out[key]=e;
      } else if(key==='disciple.status'){
        var st = sanitizeStr(v, 8);
        if(st && STATUS_SET.indexOf(st)>=0) out[key]=st;
      } else if(STR_MAX[key]!=null){
        var sv = sanitizeStr(v, STR_MAX[key]);
        if(sv!==undefined) out[key]=sv;
      }
    });
    return out;
  }
  function setPath(obj, path, val){
    var ps = path.split('.'), o = obj;
    for(var i=0;i<ps.length-1;i++){ if(typeof o[ps[i]]!=='object'||o[ps[i]]==null) o[ps[i]]={}; o=o[ps[i]]; }
    o[ps[ps.length-1]] = val;
  }
  function getPath(obj, path){
    var ps = path.split('.'), o = obj;
    for(var i=0;i<ps.length;i++){ if(o==null) return undefined; o=o[ps[i]]; }
    return o;
  }
  function commitToState(patch, source){
    try {
      var clean = sanitizePatch(patch);
      var keys = Object.keys(clean);
      if(!keys.length) return;
      var d = load();
      var changed = false;
      keys.forEach(function(key){
        var owner = FIELD_OWNER[key];
        if(!owner) return;
        if(owner==='lock'){
          var cur = getPath(d, key);
          if(cur==null || cur===''){ setPath(d, key, clean[key]); changed=true; }
          return;
        }
        if(owner==='arb'){ setPath(d, key, clean[key]); changed=true; return; }
        if(owner!==source) return;
        setPath(d, key, clean[key]); changed=true;
      });
      if(changed) {
        save(d);
        // emotion 变化时同步 Live2D 表情
        if(clean['disciple.emotion']) l2dSetExpression(clean['disciple.emotion']);
      }
    } catch(e){ console.warn('[徒弟系统] commit skip', e); }
  }

