  // delta 正=入账(返利)，负=支出(剧情消费)；why 记账原因；kind 'rebate'|'spend'|'other'
  function applyBalanceDelta(delta, why, kind){
    delta = sanitizeNumber(delta, -1e12, 1e12, true);
    if(delta===undefined || delta===0) return;
    var d = load();
    var before = Number(d.econ.balance)||0;
    var after = before + delta;
    if(after < 0) after = 0;
    d.econ.balance = after;
    if(delta > 0){
      d.econ.rebateLog.unshift({ day:d.meta.day, amt:delta, why: why || (kind==='rebate'?'返利':'入账') });
      d.econ.rebateLog = d.econ.rebateLog.slice(0,30);
    }
    save(d);
  }

