  function loadScript(src){
    return new Promise(function(resolve, reject){
      if(D.querySelector('script[src="'+src+'"]')){ resolve(); return; }
      var s = D.createElement('script'); s.src = src; s.async = false;
      s.onload = resolve;
      s.onerror = function(){ reject(new Error('脚本加载失败: '+src)); };
      (D.head||D.body).appendChild(s);
    });
  }
  function waitFor(cond, timeout, interval){
    return new Promise(function(resolve){
      var waited = 0; interval = interval || 60; timeout = timeout || 3000;
      (function tick(){
        var ok = false; try { ok = !!cond(); } catch(_){ ok = false; }
        if(ok){ resolve(true); return; }
        waited += interval;
        if(waited >= timeout){ resolve(false); return; }
        setTimeout(tick, interval);
      })();
    });
  }
  async function loadScriptRace(cands, validate){
    var lastErr = null;
    for(var i=0;i<cands.length;i++){
      try {
        await loadScript(cands[i]);
        if(typeof validate === 'function'){
          var ready = await waitFor(validate, 3000, 60);
          if(!ready){ lastErr = new Error('镜像内容无效(全局对象未就绪): '+cands[i]); continue; }
        }
        return cands[i];
      } catch(e){ lastErr = e; }
    }
    throw (lastErr || new Error('全部镜像均加载失败'));
  }
  function probeUrl(url){
    return fetch(url, { method:'HEAD' }).then(function(r){ return r.ok; }).catch(function(){ return false; });
  }
  async function findCore(cands){
    for(var i=0;i<cands.length;i++){
      var ok = await probeUrl(cands[i]);
      if(ok) return cands[i];
    }
    return cands[cands.length-1];
  }

  async function l2dInit(canvasId, modelUrl){
    if(_l2dLoading) return;
