      if(isCubism2){
        var core2 = await findCore(L2D_CORE2_CANDIDATES);
        await loadScript(core2);
      } else {
        var core4 = await findCore(L2D_CORE4_CANDIDATES);
        await loadScript(core4);
      }
      await loadScriptRace(L2D_LIB.pixi, function(){
        var P = (typeof PIXI !== 'undefined') ? PIXI : W.PIXI;
        return !!(P && P.Application);
      });
      W.PIXI = W.PIXI || (typeof PIXI !== 'undefined' ? PIXI : null);
