        var P = W.PIXI || ((typeof PIXI !== 'undefined') ? PIXI : null);
        return !!(P && P.live2d && P.live2d.Live2DModel);
      });
      W.PIXI = W.PIXI || ((typeof PIXI !== 'undefined') ? PIXI : null);
      if(!(W.PIXI && W.PIXI.live2d && W.PIXI.live2d.Live2DModel)){ throw new Error('Live2D 库加载失败（全部镜像内容无效）'); }
      try { if(W.PIXI.live2d && W.PIXI.live2d.Live2DModel && W.PIXI.Ticker) W.PIXI.live2d.Live2DModel.registerTicker(W.PIXI.Ticker); } catch(_){}
