    } catch(e){ console.error('[徒弟系统] 恢复楼层快照失败', e); }
    return false;
  }

  /* ============================================================
   * 世界书注入已移交 DB Core（DZDB.reinject / forMain），本脚本不再直接写世界书。
   * ============================================================ */

  /* ============================================================
   * 数值/额度/剧情日 — 保留项（增量/追加类逻辑不走 commit）
   * ============================================================ */
  function quotaCap(level) { return { touch:[5,8,12,999,999,999][level]||999, talk:[1,3,999,999,999,999][level]||999 }; }
  function refreshQuota(d) { if (d.meta.day !== d.quota.lastDay) { var c = quotaCap(d.aff.level); d.quota.touchLeft = c.touch; d.quota.talkLeft = c.talk; d.quota.lastDay = d.meta.day; } }
  function normAff(d) {
    var leveled = 0;
    while (d.aff.value >= 100 && d.aff.level < 5) { d.aff.value -= 100; d.aff.level++; leveled++; }
    while (d.aff.value < 0 && d.aff.level > 0) { d.aff.value += 100; d.aff.level--; }
    if (d.aff.value > 100 && d.aff.level >= 5) d.aff.value = 100;
    if (d.aff.value < 0) d.aff.value = 0;
    return leveled;
  }
  function advanceDay(d, newDay){ if (newDay > d.meta.day) { d.meta.day = newDay; d.meta.dayStart = Date.now(); d.meta.shopRefresh = true; } }
  function applyShopRefresh(d){
    if (!d.meta.shopRefresh) return;
    d.meta.shopRefresh = false;
    // 剧情日变化：整体替换，清空所有商品（含未售罄），等 AI 重新生成
    d.phone.shop = [];
  }
  function mergeNewItems(d, items){
    var given = (d.meta.recentGiven || []).slice();
    items.forEach(function(it){
      if(!it || !it.name) return;
      var gi = given.findIndex(function(g){ return g.name === it.name; });
      if (gi >= 0) { given.splice(gi, 1); return; }
      var f = d.bag.find(function(x){return x.name===it.name;});
      if (f) f.qty=(f.qty||1)+(it.qty||1); else d.bag.push({name:it.name,desc:it.desc||'',qty:it.qty||1});
    });
    d.meta.recentGiven = [];
  }

  /* ---------- 徒弟携带物（增量更新，qty:0 删除，replace 替换） ---------- */
  function setBelongings(d, items){
    if(!Array.isArray(items)) return;
    var existing = d.disciple.belongings || [];
    items.forEach(function(it){
      if(!it || !it.name) return;
      var name = sanitizeStr(it.name, 24); if(!name) return;
      var qty = (it.qty !== undefined) ? parseInt(it.qty, 10) : undefined;
      // qty <= 0：从列表中移除
      if (qty !== undefined && qty <= 0) {
        existing = existing.filter(function(x){ return x.name !== name; });
        return;
      }
      // replace：先移除被替换的旧物品
      if (it.replace) {
        var replaceName = sanitizeStr(it.replace, 24);
        if (replaceName) {
          existing = existing.filter(function(x){ return x.name !== replaceName; });
        }
      }
      var idx = existing.findIndex(function(x){ return x.name === name; });
      if (idx >= 0) {
        // 同名：覆盖更新
        if (it.desc !== undefined) existing[idx].desc = sanitizeStr(it.desc, 80);
        if (it.cat  !== undefined) existing[idx].cat  = sanitizeStr(it.cat, 8);
        if (qty !== undefined) existing[idx].qty = qty;
      } else {
        // 新增：追加
        existing.push({
          name: name,
          desc: sanitizeStr(it.desc, 80) || '',
          cat:  sanitizeStr(it.cat, 8) || '其他',
          qty:  (qty !== undefined) ? qty : 1
        });
      }
    });
    d.disciple.belongings = existing.slice(0, 40);
  }

  /* ============================================================
   * 【v5.0 重构】主 AI 变量更新解析（MVU 风格 _.set 逐行协议）
   *  取代旧 parseAndMerge(<徒弟数据> JSON 块)。
   *  格式：<状态> 内每行一个 _.set(字段, 值[, 值2...])
   *  - 标量走 commitToState('main')；余额走 applyBalanceDelta 增量
   *  - aff 用 +N/-N 增量；day 走 advanceDay；item/belonging 逐行累积
   *  - 逐行容错：单行解析失败不影响其他行
   * ============================================================ */

  // 主 AI 直接赋值的标量字段 → commit patch 的映射（单值字段）
  var SET_SCALAR_MAP = {
    'period':'meta.period', 'place':'meta.place', 'cognition':'meta.cognition',
    'affLevel':'aff.level', 'affValue':'aff.value',
    'touchLeft':'quota.touchLeft', 'talkLeft':'quota.talkLeft',
    'emotion':'disciple.emotion', 'mood':'disciple.mood',
    'status':'disciple.status', 'storyline':'disciple.storyline', 'dplace':'disciple.locale',
    'name':'disciple.name', 'age':'disciple.age', 'appearance':'disciple.appearance',
    'personality':'disciple.personality', 'world':'disciple.world',
    'plight':'disciple.plight', 'cognitionType':'disciple.cognitionType'
  };

  // 解析单行 _.set(key, rest) → { key, rest } 或 null
  function parseSetLine(line) {
    var m = line.match(/_\.set\s*\(\s*([A-Za-z]+)\s*,\s*([\s\S]*)\)\s*;?\s*$/);
    if (!m) return null;
    var key = m[1].trim();
    var rest = m[2].trim();
    // 去掉可能包裹值的引号
    rest = rest.replace(/^["'「『]+|["'」』]+$/g, '').trim();
    if (!key || rest === '') return null;
    return { key: key, rest: rest };
  }
  // 把 rest 按逗号切分为多参数（用于 rebate/spend/item/belonging）
  function splitArgs(rest) {
    return rest.split(/\s*[,，]\s*/).map(function(s){
      return s.replace(/^["'「『]+|["'」』]+$/g,'').trim();
    });
  }

  function parseSetCommands(text) {
    if (!text) return;
    var block = text.match(/<状态>([\s\S]*?)<\/状态>/);
    if (!block) return;
    var lines = block[1].split(/\r?\n/);

    // ① 增量/追加/去重类逻辑 + 标量 patch 收集
    var d = load();
    var patch = {};
    var newItems = [];        // 剧情新获道具 → 背包累加
    var belongings = null;    // 徒弟随身快照（整体替换）；有任一 belonging 行才替换
    var rebates = [];         // {amt, why}
    var spends  = [];         // {amt, why}
    var backlogText = '';

    lines.forEach(function(line) {
      var p = parseSetLine(line);
      if (!p) return;
      var key = p.key, rest = p.rest;

      if (key === 'day') {
        var nd = parseInt(rest, 10);
        if (isFinite(nd)) advanceDay(d, nd);
        return;
      }
      if (key === 'aff' || key === 'affDelta') {
        // 支持 +15 / -5 / 15 增量
        var delta = parseInt(rest.replace(/[^\-+\d]/g,''), 10);
        if (isFinite(delta) && delta !== 0) {
          d.aff.value += delta;
          var _lv = normAff(d);
          if (_lv) setTimeout(function(){ showLevelUp(d.aff.level); }, 400);
        }
        return;
      }
      if (key === 'rebate') {
        var ra = splitArgs(rest);
        var amt = parseInt(ra[0], 10);
        if (isFinite(amt) && amt !== 0) rebates.push({ amt: Math.abs(amt), why: ra[1] || '返利' });
        return;
      }
      if (key === 'spend') {
        var sa = splitArgs(rest);
        var samt = parseInt(sa[0], 10);
        if (isFinite(samt) && samt !== 0) spends.push({ amt: Math.abs(samt), why: sa[1] || '支出' });
        return;
      }
      if (key === 'item') {
        // _.set(item, 名称, 描述, 数量) —— 描述/数量可省
        var ia = splitArgs(rest);
        if (ia[0]) {
          var q = parseInt(ia[2], 10);
          newItems.push({ name: ia[0], desc: ia[1] || '', qty: (isFinite(q) && q>0) ? q : 1 });
        }
        return;
      }
      if (key === 'belonging') {
        // _.set(belonging, 名称, 类别, 描述) —— 每行一件，整体作为快照
        var ba = splitArgs(rest);
        if (ba[0]) {
          if (belongings === null) belongings = [];
          belongings.push({ name: ba[0], cat: ba[1] || '其他', desc: ba[2] || '' });
        }
        return;
      }
      if (key === 'backlog') { backlogText = rest; return; }

      // 标量字段
      var path = SET_SCALAR_MAP[key];
      if (path) patch[path] = rest;
    });

    if (newItems.length) mergeNewItems(d, newItems);
    if (belongings !== null) setBelongings(d, belongings);
    if (backlogText) {
      d.disciple.backlog.unshift({ id:uid('b'), day:d.meta.day, text:backlogText, read:false });
      d.disciple.backlog = d.disciple.backlog.slice(0,20);
    }
    refreshQuota(d);
    save(d);

    // ② 余额增量（在上面 save 之后；applyBalanceDelta 内部自 load/save）
    rebates.forEach(function(r){ applyBalanceDelta(r.amt, r.why, 'rebate'); });
    spends.forEach(function(s){ applyBalanceDelta(-s.amt, s.why, 'spend'); });

    // ③ 标量 patch 经 commit（main 权威）
    commitToState(patch, 'main');

    // ④ 额度依赖最新等级，末尾再保一次
    var d2 = load(); refreshQuota(d2); save(d2);
  }

  /* ---------- 【v5.0 兜底通道】从正文场景头标自动同步 时间/地点 ----------
   * 模型每段正文开头都会写：【场景 · 时间：第 N 日 · 时段　地点：xxx】
   * （此头标被正则渲染成样式条，模型遵从率极高）。
   * 即便模型漏写 <状态> 块，也能据此头标兜底更新 day/period/place，
   * 从根上缓解「主 AI 不更新变量」——因为地点/时间不再依赖易漏的 _.set。
   * ------------------------------------------------------------------ */
  function parseSceneHeader(text) {
    if (!text) return;
    // 只取正文首个场景头标（避免抓到正文中途引用的旧头标）
    var head = text.match(/【\s*场景[\s\S]{0,80}?】/);
    var scope = head ? head[0] : text.slice(0, 120);
    var d = load();
    var patch = {};
    // 抓天数（第 N 日）
    var dayM = scope.match(/第\s*(\d+)\s*日/);
    if (dayM) { var nd = parseInt(dayM[1], 10); if (isFinite(nd)) advanceDay(d, nd); }
    // 抓时段（枚举）
    var perM = scope.match(/(清晨|上午|午后|傍晚|深夜|夜)/);
    if (perM) patch['meta.period'] = perM[1];
    // 抓地点（地点：X，兼容全角/半角空格与冒号）
    var plM = scope.match(/地\s*点\s*[:：]\s*([^】\n]+?)\s*】/);
    if (!plM) plM = text.match(/地\s*点\s*[:：]\s*([^】\n]+?)\s*】/);
    if (plM) {
      var place = plM[1].replace(/[　\s]+$/, '').trim();
      // 权威主源：有效地点才写，避免占位/未知覆盖
      if (place && place !== '未知' && place !== '待定' && place !== '（随正文确定）') {
        patch['meta.place'] = place;
      }
    }
    save(d);
    commitToState(patch, 'main');
  }

  /* ============================================================
   * 第二 API
   * ============================================================ */
  async function callAPI(userInput, sysPrompt) {
    var a = load().api2;
    var second = a.enabled && a.url && a.key && a.model;
    var req = { user_input:userInput, ordered_prompts:[{ role:'system', content:sysPrompt }, 'user_input'] };
    if (second) req.custom_api = { apiurl:a.url, key:a.key, model:a.model, source:a.source||'openai' };
    try { return { ok:true, text: await generateRaw(req) }; }
    catch (e) {
      if (second) {
        toast('error', '第二 API 失败，改用主 API：' + (e && e.message || e));
        try { return { ok:true, text: await generateRaw({ user_input:userInput, ordered_prompts:[{ role:'system', content:sysPrompt }, 'user_input'] }) }; }
        catch (e2) { return { ok:false, text:'', err:e2 }; }
      }
      return { ok:false, text:'', err:e };
    }
  }
  function extractJSON(t) {
    if (!t) return null;
    t = String(t).replace(/```json/gi,'```').trim();
    var f = t.match(/```([\s\S]*?)```/); if (f) t = f[1].trim();
    var s = t.indexOf('{'), e = t.lastIndexOf('}'); if (s<0||e<0) return null;
    try { return JSON.parse(t.slice(s, e+1)); } catch (_) { return null; }
  }
  function recentStory() {
    try { var m = getChatMessages(-1); var t = (m && m[0] && m[0].message) || ''; return t.replace(/<状态>[\s\S]*?<\/状态>/g,'').replace(/<徒弟数据>[\s\S]*?<\/徒弟数据>/g,'').slice(-800); }
    catch (_) { return ''; }
  }

  /* ---------- 【v6.0】补抓最新楼层状态（兜底：开场白/未被hook处理的楼层） ----------
   * 开场白(greeting)不触发 CHARACTER_MESSAGE_RENDERED，其 <状态> 块(含 spend/rebate)
   * 不会被 hook 解析 → 余额等不更新。打开手机时补抓一次，幂等（重复行不会重复扣款：
   * balance 走账本、aff 增量已被解析过则不再触发；但开场白仅解析一次风险低）。
   * 为避免重复应用，用最新楼层 message_id 做去重标记。
   * ------------------------------------------------------------------ */
  function catchUpParse() {
    try {
      var lastId = (typeof getLastMessageId === 'function') ? getLastMessageId() : -1;
      var arr = getChatMessages(-1); var msg = arr && arr[0];
      if (!msg || !msg.message) return;
      var txt = msg.message;
      if (!/<状态>|【场景/.test(txt)) return;
      var d = load();
      // 去重：该楼层已补抓过则跳过
      if (d.meta.lastCatchUp != null && d.meta.lastCatchUp === lastId) return;
      d.meta.lastCatchUp = lastId; saveRaw(d);
      parseSceneHeader(txt);
      parseSetCommands(txt);
    } catch (e) { console.warn('[徒弟系统] catchUpParse skip', e); }
  }

  /* ---------- 【模块2】联系人身份解析 ---------- */
  function resolveContact(d, rawName){
    var name = normalizeName(rawName);
    // 被宿主删除的联系人：拒绝重建，不再接收任何消息
    var blocked = d.phone.deletedContacts || [];
    var pidCheck = findByAlias(name);
    if(blocked.some(function(b){ return (b.name&&normalizeName(b.name)===name) || (pidCheck&&b.id===pidCheck); })) return null;
    var pid = findByAlias(name);
    if(pid){
      var c = d.phone.contacts.find(function(x){ return x.id===pid; });
      if(!c){ var p=presetById(pid); c={ id:p.id, name:p.name, preset:p.preset, realWorld:p.realWorld, aliases:p.aliases.slice(), msgs:[] }; d.phone.contacts.push(c); }
      return c;
    }
    var exact = d.phone.contacts.find(function(x){ return !presetById(x.id) && normalizeName(x.name)===name; });
    if(exact) return exact;
    var nc = { id:uid('c'), name:name||'某人', preset:'剧情中出现的人物', realWorld:true, aliases:[name], msgs:[] };
    d.phone.contacts.push(nc);
    return nc;
  }
  /* ---------- 【模块3】现有联系人规范名清单 ---------- */
  function buildContactRoster(d){
    var names = (d.phone.contacts||[]).map(function(c){ return c.name; }).filter(Boolean);
    return names.join('、') || '（暂无）';
  }

  /* ---------- 【v6.0】现实侧内容写回（与徒弟状态正交，无条件执行） ----------
   * 处理：新闻 / 通用商品 / 联系人短信。不依赖徒弟是否存在，不受离线门控约束。
   * 这是"联系人不自动加"的核心修复：contactMsgs 独立于徒弟侧写回。
   * ------------------------------------------------------------------ */
  function applyRealSide(pkg, gameDay){
    if(!pkg) return 0;
    var wrote = 0;
    var d2 = load();
    if (Array.isArray(pkg.shopNew)) {
    // 先替换已售罄的商品，再追加新商品，最后裁剪到5件
    var shop = d2.phone.shop || [];
    pkg.shopNew.forEach(function(g){
      if(!g||!g.name) return;
      // 已存在同名商品：跳过
      if(shop.some(function(x){return x.name===g.name;})) return;
      var lim = g.limit>0?g.limit:1;
      var newItem = { id:uid('s'), name:g.name, desc:g.desc||'', price:g.price||0, tier:g.tier||'普通', limit:lim, stock:lim, bornDay:Math.floor(d2.meta.gameDay) };
      // 找已售罄的空位替换
      var soldIdx = shop.findIndex(function(x){ return (x.stock||0) <= 0; });
      if (soldIdx >= 0) {
        shop[soldIdx] = newItem;
      } else {
        shop.push(newItem);
      }
      wrote++;
    });
    // 裁剪到5件：1高+2中+2低
    var high = ['稀有','史诗','逆天'];
    var highItems = [], midItems = [], lowItems = [];
    shop.forEach(function(g){
      if ((g.stock||0) <= 0) return; // 裁剪时也清除售罄
      if (high.indexOf(g.tier) >= 0) highItems.push(g);
      else if (g.tier === '精良') midItems.push(g);
      else lowItems.push(g);
    });
    highItems.sort(function(a,b){ return (b.bornDay||0) - (a.bornDay||0); });
    midItems.sort(function(a,b){ return (b.bornDay||0) - (a.bornDay||0); });
    lowItems.sort(function(a,b){ return (b.bornDay||0) - (a.bornDay||0); });
    var capped = [];
    if (highItems.length > 0) capped.push(highItems[0]);
    midItems.slice(0, 2).forEach(function(g){ capped.push(g); });
    lowItems.slice(0, 2).forEach(function(g){ capped.push(g); });
    d2.phone.shop = capped;
  }
    if (Array.isArray(pkg.newsNew)) pkg.newsNew.forEach(function(n){
      if(!n||!n.title) return;
      if((d2.phone.news||[]).some(function(x){return x.title===n.title;})) return;
      d2.phone.news.unshift({ id:uid('n'), title:n.title, summary:n.summary||'', read:false, day:d2.meta.day });
      wrote++;
    });
    d2.phone.news = d2.phone.news.slice(0,40);
    // 联系人短信 → resolveContact 归并（无门控）
    if (Array.isArray(pkg.contactMsgs)) pkg.contactMsgs.forEach(function(cm){
      if(!cm||!cm.from||!cm.content) return;
      if(/未知号码|未知|陌生号码/.test(cm.from)) return;
      var c = resolveContact(d2, cm.from);
      if(!c) return;
      if(c.preset==='剧情中出现的人物' && cm.preset) c.preset = cm.preset;
      var dup = (c.msgs||[]).some(function(m){ return m.role==='them' && m.text===cm.content; });
      if(dup) return;
      c.msgs.push({ role:'them', text:cm.content, read:false, t:Date.now() });
      c.msgs = c.msgs.slice(-60);
      wrote++;
    });
    save(d2);
    return wrote;
  }

  /* ---------- 【v6.0】徒弟侧内容写回（门控：未收徒跳过；离线窗口才可改处境） ---------- */
  function applyDiscipleSide(pkg, gameDay, offlineWindow){
    if(!pkg) return;
    var d0 = load();
    if(!d0.disciple.name) return; // 未收徒：徒弟侧全部跳过
    var s = pkg.sync || {};
    var patch = {};
    if (s.emotion) patch['disciple.emotion'] = s.emotion;
    if (s.mood)    patch['disciple.mood']    = s.mood;
    if (offlineWindow) {
      if (s.status)    patch['disciple.status']    = s.status;
      if (s.storyline) patch['disciple.storyline'] = s.storyline;
      if (s.locale)    patch['disciple.locale']    = s.locale;
    }
    commitToState(patch, 'phone');
    var d2 = load();
    if (Array.isArray(s.newItems)) mergeNewItems(d2, s.newItems);
    if (Array.isArray(s.belongings)) setBelongings(d2, s.belongings);
    refreshQuota(d2);
    save(d2);
    if (pkg.backlog && String(pkg.backlog).trim()) {
      var d3 = load();
      d3.disciple.backlog.unshift({ id:uid('b'), day: gameDay, text: String(pkg.backlog).trim(), read:false });
      d3.disciple.backlog = d3.disciple.backlog.slice(0,20);
      save(d3);
    }
  }

  async function genPhone() {
    var d = load();
    var phoneOpen = !!D.getElementById('ph-mask');
    var realNow = d.meta.day || 1;
    var dReal = Math.max(0, realNow - (d.meta.lastRealDay != null ? d.meta.lastRealDay : realNow));
    var offlineWindow = dReal > 0; // 【离线门控】仅真过了现实时间(无人观察)才允许第二API改处境/写危机
    var curStatus = d.disciple.status || '安好';
    var curStoryline = d.disciple.storyline || '';
    var mult = phoneOpen ? 1 : 3;
    d.meta.gameDay = (d.meta.gameDay || 1) + dReal * mult;
    d.meta.lastRealDay = realNow;
    applyShopRefresh(d);
    saveRaw(d);
    var gameDay = Math.floor(d.meta.gameDay);
    var existShop = (d.phone.shop||[]).map(function(g){return g.name;}).join('、')||'无';
    var existNews = (d.phone.news||[]).slice(0,10).map(function(n){return n.title;}).join('｜')||'无';
