  async function fetchModels() {
    var a = load().api2;
    if (!a.url || !a.key) { toast('warning', '请先填写 API 地址与密钥'); return; }
    var raw = a.url.trim().replace(/\/+$/, ''); var root = raw.replace(/\/v1(beta)?$/i, '');
    var bearer = { Authorization:'Bearer ' + a.key }; var claudeH = { 'x-api-key':a.key, 'anthropic-version':'2023-06-01' };
    var pOA = function (j){ return (j.data||j.models||[]).map(function(m){return m.id||m.name;}); };
    var pG  = function (j){ return (j.models||[]).map(function(m){return (m.name||'').replace(/^models\//,'');}); };
    var cands = [];
    if (a.source === 'makersuite' || a.source === 'gemini') cands.push([root+'/v1beta/models?key='+encodeURIComponent(a.key), {}, pG]);
    cands.push([raw+'/models', bearer, pOA]); cands.push([root+'/v1/models', bearer, pOA]); cands.push([raw+'/models', claudeH, pOA]);
    var seen={}, uniq=[]; cands.forEach(function(c){var k=c[0]+JSON.stringify(c[1]);if(!seen[k]){seen[k]=1;uniq.push(c);}});
    toast('info', '正在抓取模型列表…');
    for (var i=0;i<uniq.length;i++) {
      try {
        var resp = await fetch(uniq[i][0], { headers: uniq[i][1] });
        if (!resp.ok) continue;
        var list = (uniq[i][2](await resp.json())||[]).filter(Boolean);
        if (list.length) { var d=load(); d.api2.models=list; saveRaw(d); toast('success','拉取到 '+list.length+' 个模型'); renderScreen('settings'); return; }
      } catch (e) {}
    }
    toast('error', '抓取失败：地址/密钥有误或存在 CORS 限制，可手动填模型名');
  }

