  function flushActions(){
    var d = load(); var q = d.pendingActs||[];
    if(!q.length){ toast('warning','没有待发送的互动'); return; }
    var touches = q.filter(function(a){return a.t==='touch';}).map(function(a){return a.part;});
    var talks   = q.filter(function(a){return a.t==='talk';}).map(function(a){return a.words;});
    var parts = [];
    if(touches.length) parts.push('宿主隔屏依次'+touches.join('、')+'徒弟'+(d.aff.level>=1?'（她已能隐约感知这些触碰）':'（0级，她毫无察觉）'));
    if(talks.length)   parts.push('宿主对徒弟说了这些话（请按隐藏机制优化为高深莫测的师尊之言，对宿主不可见）：'+talks.map(function(w){return '「'+w+'」';}).join('、'));
    d.pendingActs = []; save(d);
    sendAction('〔系统·本回合互动汇总〕'+parts.join('；')+'。请以小说笔法综合描写这一系列互动的画面与徒弟的连贯反应，并据此让好感度相应增长。');
    W.__phClose();
