  function recordGiven(d, name, qty){
    if(!d.meta.recentGiven) d.meta.recentGiven = [];
    d.meta.recentGiven.push({ name:name, qty:qty, at:Date.now() });
    if(d.meta.recentGiven.length > 40) d.meta.recentGiven = d.meta.recentGiven.slice(-40);
  }
  function bagDeduct(d, name, qty){
    var idx = d.bag.findIndex(function(x){ return x.name === name; });
    if (idx < 0) return 0;
    var have = d.bag[idx].qty || 1;
    qty = Math.max(1, Math.min(qty || 1, have));
    d.bag[idx].qty = have - qty;
    if (d.bag[idx].qty <= 0) d.bag.splice(idx, 1);
    recordGiven(d, name, qty);
    return qty;
  }
  function doGift(name, qty) {
    var d = load();
    var bagItem = d.bag.find(function(x){ return x.name===name; });
    var desc = (bagItem && bagItem.desc) ? '（效果：'+bagItem.desc+'）' : '';
    var got = bagDeduct(d, name, qty); if(!got){ toast('warning','背包里没有该道具'); return; }
    save(d);
    var q = got>1?('（共 '+got+' 份）'):'';
    sendAction('〔系统·赠礼〕宿主将【'+name+'】'+desc+q+'赠予徒弟。请严格按照上述道具描述来描写其效果与徒弟的反应，按契合度让好感增长；若利于徒弟则触发返利。');
    renderScreen('bag');
  }
  function doExtract(name, qty) {
    var d = load();
    var bagItem = d.bag.find(function(x){ return x.name===name; });
    var desc = (bagItem && bagItem.desc) ? '（效果：'+bagItem.desc+'）' : '';
    var got = bagDeduct(d, name, qty); if(!got){ toast('warning','背包里没有该道具'); return; }
    var cog = d.meta.cognition || '懵懂'; save(d);
    var q = got>1?('（共 '+got+' 份）'):'';
    var how = (cog === '觉醒') ? '宿主已觉醒，请描写【'+name+'】'+q+'直接凭空出现在宿主面前。'
      : '宿主尚未完全确信系统为真（认知：'+cog+'），请描写【'+name+'】'+q+'以看似合理的方式送达现实（快递、门口包裹、意外中奖等），像巧合。';
    sendAction('〔系统·提取到现实〕宿主将修仙界的【'+name+'】'+desc+q+'提取到现实。'+how+'请严格按照上述道具描述来描写其效果与宿主的反应。');
    renderScreen('bag');
  }
  function doBuy(name, id, qty) {
    var d = load();
    var g = d.phone.shop.find(function(x){return x.id===id;});
    if(!g){ toast('warning','该商品已下架'); return; }
    qty = Math.max(1, qty||1);
    if (qty > g.stock) { toast('warning','库存不足，仅剩 '+g.stock+' 件'); return; }
    var total = g.price * qty;
    if (d.econ.balance < total) { toast('warning','余额不足，需 '+money(total)+'，现有 '+money(d.econ.balance)); return; }
    d.econ.balance -= total; d.econ.coin += total; g.stock -= qty;
    var f = d.bag.find(function(x){return x.name===name;});
    if (f) f.qty=(f.qty||1)+qty; else d.bag.push({name:name,desc:g.desc||'',qty:qty});
    save(d);
    toast('success','已购买【'+name+'】x'+qty+'，花费 '+money(total));
    renderScreen('shop');
  }

