  function buildGraphData() {
  var d = load();
  var npc = d.head && d.head.npc;
  if (!npc) return { nodes: [], links: [] };
  var blNames = (d.phone.deletedContacts || []).map(function(b){ return b.name; });
  var nodes = [], links = [], linkMap = {};
  Object.keys(npc).forEach(function(k){
    var n = npc[k];
    if (blNames.indexOf(k) >= 0) return;
    nodes.push({
      id: k,
      name: n.name || k,
      relation: n.relation || '',
      preset: n.preset || '',
      dynamic: n.dynamic || '',
      realWorld: n.realWorld !== false,
      msgs: n.msgs || [],
      alias: (n.aliases && n.aliases[0]) || k
    });
  });
  var relGroups = {};
  nodes.forEach(function(n){
    if (!n.relation) return;
    if (!relGroups[n.relation]) relGroups[n.relation] = [];
    relGroups[n.relation].push(n.id);
  });
  Object.keys(relGroups).forEach(function(rel){
    var group = relGroups[rel];
    for (var i = 0; i < group.length; i++) {
      for (var j = i + 1; j < group.length; j++) {
        var key = [group[i], group[j]].sort().join('|');
        if (!linkMap[key]) {
          linkMap[key] = true;
          links.push({ source: group[i], target: group[j], relation: rel });
        }
      }
    }
  });
  return { nodes: nodes, links: links };
}

function forceLayout(graph, width, height) {
  var nodes = graph.nodes;
  var links = graph.links;
  if (!nodes.length) return;
  var cx = width / 2, cy = height / 2;
  var centerForce = 0.01;
  var repulsionForce = 800;
  var attractForce = 0.005;
  var minDist = 60;
  nodes.forEach(function(n){
    n.x = cx + (Math.random() - 0.5) * width * 0.4;
    n.y = cy + (Math.random() - 0.5) * height * 0.4;
    n.vx = 0; n.vy = 0;
  });
  for (var iter = 0; iter < 80; iter++) {
    for (var i = 0; i < nodes.length; i++) {
      for (var j = i + 1; j < nodes.length; j++) {
        var a = nodes[i], b = nodes[j];
        var dx = a.x - b.x, dy = a.y - b.y;
        var dist = Math.sqrt(dx * dx + dy * dy) || 1;
        var force = repulsionForce / (dist * dist);
        var fx = dx / dist * force, fy = dy / dist * force;
        a.vx += fx; a.vy += fy;
        b.vx -= fx; b.vy -= fy;
      }
    }
    links.forEach(function(l){
      var src = null, tgt = null;
      for (var k = 0; k < nodes.length; k++) {
        if (nodes[k].id === l.source) src = nodes[k];
        if (nodes[k].id === l.target) tgt = nodes[k];
      }
      if (!src || !tgt) return;
      var dx = tgt.x - src.x, dy = tgt.y - src.y;
      var dist = Math.sqrt(dx * dx + dy * dy) || 1;
      var force = dist * attractForce;
      var fx = dx / dist * force, fy = dy / dist * force;
      src.vx += fx; src.vy += fy;
      tgt.vx -= fx; tgt.vy -= fy;
    });
    nodes.forEach(function(n){
      n.vx += (cx - n.x) * centerForce;
      n.vy += (cy - n.y) * centerForce;
    });
    nodes.forEach(function(n){
      n.vx *= 0.9; n.vy *= 0.9;
      n.x += n.vx; n.y += n.vy;
      n.x = Math.max(minDist, Math.min(width - minDist, n.x));
      n.y = Math.max(minDist, Math.min(height - minDist, n.y));
    });
  }
}

