  function scDiscipleBag() {
    var d = load();
    var items = d.disciple.belongings || [];
    var CAT_ICON = { '衣物':'👗','道具':'🧪','饰品':'💍','武器':'🗡️','其他':'📦' };
    // 按类别分组
    var groups = {};
    items.forEach(function(it){
      var cat = it.cat || '其他';
      if(!groups[cat]) groups[cat] = [];
      groups[cat].push(it);
    });
    var order = ['衣物','饰品','武器','道具','其他'];
    var cats = Object.keys(groups).sort(function(a,b){
      var ia=order.indexOf(a), ib=order.indexOf(b);
      return (ia<0?99:ia)-(ib<0?99:ib);
    });
    var body = '';
    if (!items.length) {
      body = '<div style="color:var(--text-sec);font-size:14px;text-align:center;padding:32px;">尚不清楚她身上带着什么<br><span style="font-size:12px;">（随剧情推进自动更新）</span></div>';
    } else {
      body = cats.map(function(cat){
        var rows = groups[cat].map(function(it){
          var qtyBadge = (it.qty && it.qty > 1) ? ' <span style="color:var(--accent);font-size:12px;font-weight:600;background:var(--accent-dim);padding:1px 7px;border-radius:8px;">×'+it.qty+'</span>' : '';
          return '<div class="ph-rise" style="display:flex;align-items:flex-start;gap:10px;padding:14px 16px;margin-bottom:10px;background:var(--card-bg);border:1px solid var(--border);border-radius:18px;box-shadow:var(--shadow);">'+
            '<div style="font-size:24px;flex:0 0 auto;line-height:1.2;">'+(CAT_ICON[cat]||'📦')+'</div>'+
            '<div style="min-width:0;flex:1;"><b style="color:var(--text-main);font-size:15px;">'+(it.name||'')+qtyBadge+'</b>'+
            (it.desc?('<div style="color:var(--text-sec);font-size:13px;margin-top:4px;line-height:1.5;">'+it.desc+'</div>'):'')+'</div></div>';
        }).join('');
        return '<div class="ph-sec" style="margin-top:18px;">'+(CAT_ICON[cat]||'📦')+' '+cat+'</div>'+rows;
      }).join('');
    }
    var tip = '<div style="text-align:center;color:var(--text-sec);font-size:11px;margin-top:16px;line-height:1.6;">这是她随身携带的物品，仅供你查看<br>你无法取用，只有她自己能使用</div>';
