  /* ============================================================
   * 【v7.0】数据库可视化面板（思维导图式树状视图）
   *  技术：原生 <details>/<summary> + CSS 伪元素连线，零外部依赖。
   *  数据源：DZDB.load().head（全量五域），全量+折叠：重点默认展开、内部字段收起。
   * ============================================================ */
  // 字段中文名映射（顶层域 + 常见字段）
  var DB_LABELS = {
    host:'宿主', disciple:'徒弟', meta:'时间地点', npc:'人物档案', phone:'手机', ui:'界面设置',
    affLevel:'好感等级', affValue:'好感值', balance:'银行卡余额', coin:'累计充值', rebateLog:'返利账本',
    touchLeft:'剩余触摸', talkLeft:'剩余对话', name:'姓名', age:'年龄', appearance:'外貌',
    personality:'性格', world:'出身世界观', plight:'绝境', cognitionType:'认知类型',
    emotion:'表情', mood:'心情', status:'处境', storyline:'处境描述', locale:'所在环境',
    belongings:'随身物', backlog:'离线经历', day:'现实日', gameDay:'徒界日', period:'时段',
    place:'当前地点', cognition:'认知阶段', shop:'商城', news:'新闻', bag:'背包',
    grievances:'（废弃）', deletedContacts:'黑名单', relation:'关系', dynamic:'近况',
    preset:'人设', realWorld:'现实人物', lastSeen:'最近登场', msgs:'短信记录', generated:'已生成'
  };
  // 默认收起的"内部字段"（点开才看）
  var DB_COLLAPSE = { lastCatchUp:1, dayStart:1, shopRefresh:1, lastRealDay:1, recentGiven:1,
    quotaDay:1, coin:1, seenBacklog:1, aliases:1, id:1, ver:1, at:1, t:1, read:1, api2:1, models:1 };
  // 顶层域默认展开的重点
  var DB_OPEN_DOMAINS = { disciple:1, npc:1, host:1, meta:1 };

  function dbEsc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function dbLabel(k){ return DB_LABELS[k] || k; }

  // 递归渲染一个节点为 <details>/<summary> 或叶子行
  function dbNode(key, val, depth, forceCollapse){
    var label = dbLabel(key);
    var isLeaf = (val === null || typeof val !== 'object');
    if (isLeaf){
      var show = (val===''||val==null) ? '<span style="color:var(--text-sec);">—</span>' : dbEsc(val);
      return '<li class="dz-leaf"><span class="dz-k">'+dbEsc(label)+'</span><span class="dz-v">'+show+'</span></li>';
    }
    // 对象/数组
    var isArr = Array.isArray(val);
    var keys = isArr ? val.map(function(_,i){return i;}) : Object.keys(val);
    var count = keys.length;
    var summ = '<span class="dz-k">'+dbEsc(label)+'</span><span class="dz-cnt">'+(isArr?('['+count+']'):('{'+count+'}'))+'</span>';
    if (count===0){
      return '<li class="dz-leaf"><span class="dz-k">'+dbEsc(label)+'</span><span class="dz-v" style="color:var(--text-sec);">空</span></li>';
    }
    // 是否默认展开：顶层重点域展开；被标记内部字段/强制则收起
    var openAttr = '';
    if (!forceCollapse && depth===0 && DB_OPEN_DOMAINS[key]) openAttr=' open';
    else if (!forceCollapse && depth===1) openAttr=' open';   // 二级(如具体人物/徒弟字段)默认展开
    var childCollapse = !!DB_COLLAPSE[key];
    var inner = keys.map(function(k){
      var ck = isArr ? ('#'+(k+1)) : k;
      var cv = isArr ? val[k] : val[k];
      // 数组元素若是对象，用序号label
      if (isArr){
        if (cv===null||typeof cv!=='object') return '<li class="dz-leaf"><span class="dz-k">'+ck+'</span><span class="dz-v">'+dbEsc(cv)+'</span></li>';
        // 对象数组：尝试用 name/title/why 做标题
        var t = (cv.name||cv.title||cv.why||cv.text||ck);
        return dbNode('#'+(k+1)+' '+t, cv, depth+1, childCollapse);
      }
      return dbNode(k, cv, depth+1, childCollapse || !!DB_COLLAPSE[k]);
    }).join('');
    return '<li><details'+openAttr+'><summary>'+summ+'</summary><ul class="dz-tree">'+inner+'</ul></details></li>';
  }

  /* ============================================================
   * 【M4】师门 App —— 多徒弟管理 3×3 首屏
   * ------------------------------------------------------------
   * 数据源：直连 DZDB.load()（拿 raw head），不走 load()（单徒兼容视图）
   * 交互：格子点=切换活跃 + 打开详情；空位=收徒
   * ============================================================ */
  var SECT_MAX = 9;
  function _sectHead(){
    var db = _db();
    if (!db || !db.load) return null;
    try { return db.load().head; } catch(_) { return null; }
  }
  function _sectEmoji(d){
    return ({happy:'😊',shy:'😳',sad:'😢',angry:'😠',cry:'😭',calm:'🙂'})[d && d.emotion] || '🙂';
  }
  function _sectWorldName(head, worldId){
    var w = (head.worlds || []).filter(function(x){ return x && x.id === worldId; })[0];
    return w ? w.name : '';
  }
  function _sectSlot(head, idx){
    var arr = head.disciples || [];
    var d = arr[idx];
    var activeId = head.active && head.active.discipleId;
    if (!d) {
      // 空位 —— 收徒
      return '<div class="ph-tap ph-rise" onclick="window.__phSectRecruit()" '+
        'style="animation-delay:'+(idx*0.03)+'s;aspect-ratio:1/1;border-radius:18px;'+
        'background:var(--card-bg);border:1.5px dashed var(--border);'+
        'display:flex;flex-direction:column;align-items:center;justify-content:center;'+
        'cursor:pointer;color:var(--text-sec);">'+
        '<div style="font-size:28px;line-height:1;margin-bottom:6px;">＋</div>'+
        '<div style="font-size:11.5px;font-weight:600;">收徒</div>'+
        '</div>';
    }
    var isActive = d.id === activeId;
    var lv = (d.aff && d.aff.level) || 0;
    var worldName = _sectWorldName(head, d.worldId);
    var ring = isActive
      ? 'border:2px solid var(--accent);box-shadow:0 4px 14px rgba(0,122,255,.28);'
      : 'border:1px solid var(--border);box-shadow:var(--shadow);';
    var badge = isActive
      ? '<span style="position:absolute;top:6px;right:6px;background:var(--accent);color:#fff;font-size:9.5px;font-weight:700;padding:2px 6px;border-radius:8px;line-height:1;">活跃</span>'
      : '';
    return '<div class="ph-tap ph-rise" onclick="window.__phSectTap(\''+d.id+'\')" '+
      'style="animation-delay:'+(idx*0.03)+'s;position:relative;aspect-ratio:1/1;border-radius:18px;'+
      'background:var(--card-bg);'+ring+
      'padding:10px 6px;display:flex;flex-direction:column;align-items:center;justify-content:center;'+
      'cursor:pointer;overflow:hidden;">'+badge+
      '<div style="font-size:28px;line-height:1;margin-bottom:6px;">'+_sectEmoji(d)+'</div>'+
      '<div style="color:var(--text-main);font-size:12.5px;font-weight:700;letter-spacing:-0.2px;'+
        'max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+
        (d.name || '未命名')+'</div>'+
      '<div style="color:var(--text-sec);font-size:10.5px;margin-top:2px;">Lv.'+lv+
        (worldName?(' · '+worldName):'')+'</div>'+
      '</div>';
  }
  function scRelationGraph() {
  var graph = buildGraphData();
  if (!graph.nodes.length) return wrap('关系图', '<div style="text-align:center;color:var(--text-sec);padding:40px;">暂无联系人数据</div>');
  var w = 360, h = 460;
  forceLayout(graph, w, h);
  var nodes = graph.nodes, links = graph.links;
  var relColors = {
    '师徒': '#667EEA', '挚友': '#34C759', '好友': '#34C759',
    '债主': '#FF3B30', '亲人': '#FF9A9E', '父母': '#FF9A9E',
    '服务号': '#8A94A6', '系统': '#8A94A6'
  };
  function linkColor(rel) { return relColors[rel] || '#FDBB2D'; }
  var lines = links.map(function(l){
    var src = null, tgt = null;
    for (var k = 0; k < nodes.length; k++) {
      if (nodes[k].id === l.source) src = nodes[k];
      if (nodes[k].id === l.target) tgt = nodes[k];
    }
    if (!src || !tgt) return '';
    var color = linkColor(l.relation);
    return '<line x1="'+src.x+'" y1="'+src.y+'" x2="'+tgt.x+'" y2="'+tgt.y+'" stroke="'+color+'" stroke-width="2" stroke-opacity="0.6"/>';
  }).join('');
  var circles = nodes.map(function(n){
    var color = n.realWorld ? '#4FACFE' : '#8A94A6';
    var label = n.name.charAt(0);
    var escName = n.name.replace(/'/g,"\\'");
    return '<circle cx="'+n.x+'" cy="'+n.y+'" r="24" fill="'+color+'" stroke="#fff" stroke-width="2.5" opacity="0.95" style="cursor:pointer;" onclick="window.__phGraphDetail(\''+escName+'\')"/>'+
      '<text x="'+n.x+'" y="'+n.y+'" text-anchor="middle" dominant-baseline="central" fill="#fff" font-size="15" font-weight="700" style="pointer-events:none;">'+label+'</text>'+
      '<text x="'+n.x+'" y="'+(n.y+36)+'" text-anchor="middle" fill="var(--text-sec)" font-size="10" style="pointer-events:none;">'+n.name+'</text>';
  }).join('');
  var svg = '<svg viewBox="0 0 '+w+' '+h+'" style="width:100%;height:auto;display:block;margin-top:8px;">' + lines + circles + '</svg>';
  var usedRels = {};
  links.forEach(function(l){ usedRels[l.relation] = true; });
  var legendItems = Object.keys(usedRels).map(function(rel){
    return '<span style="display:inline-flex;align-items:center;gap:4px;margin:0 8px 4px 0;font-size:11px;color:var(--text-sec);"><span style="width:12px;height:3px;border-radius:2px;background:'+linkColor(rel)+';display:inline-block;"></span>'+rel+'</span>';
  }).join('');
  var legend = legendItems ? '<div style="text-align:center;padding:6px 0 0;">'+legendItems+'</div>' : '';
  var info = '<div style="text-align:center;color:var(--text-sec);font-size:11px;padding:2px 0 0;">共 '+nodes.length+' 个节点，'+links.length+' 条关系连线</div>';
  return wrap('🕸️ 关系图', svg + legend + info);
}

function scSect(){
    var head = _sectHead();
    if (!head) return wrap('师门','<div style="text-align:center;color:var(--text-sec);padding:40px;font-size:14px;">DZDB 数据库未就绪</div>');
    var disciples = head.disciples || [];
    var namedCount = disciples.filter(function(x){ return x && x.name; }).length;
    var worldCount = (head.worlds || []).length;
    var achCount   = (head.host && head.host.achievements || []).length;
    var hostName   = (head.host && head.host.name) || '';
    // 顶部：宿主 widget
    var widget = '<div class="ph-rise" style="margin:6px 4px 20px;padding:20px;border-radius:24px;'+
      'background:linear-gradient(160deg,rgba(0,122,255,.12),rgba(88,86,214,.08));'+
      'border:1px solid var(--border);box-shadow:var(--shadow);">'+
      '<div style="display:flex;justify-content:space-between;align-items:baseline;">'+
        '<div>'+
          '<div style="color:var(--text-sec);font-size:12px;font-weight:600;letter-spacing:.5px;">SECT MASTER</div>'+
          '<div style="color:var(--text-main);font-size:22px;font-weight:800;letter-spacing:-0.4px;margin-top:2px;">'+
            (hostName || '尚未署名')+'</div>'+
        '</div>'+
        '<div class="ph-press" onclick="window.__phSectRenameHost()" '+
          'style="color:var(--accent);font-size:12px;font-weight:600;cursor:pointer;padding:6px 10px;border-radius:12px;background:var(--accent-dim);">改名</div>'+
      '</div>'+
      '<div style="height:1px;background:var(--hair);margin:12px 0;"></div>'+
      '<div style="display:flex;justify-content:space-around;text-align:center;">'+
        '<div><div style="color:var(--text-main);font-size:20px;font-weight:800;">'+namedCount+'<span style="color:var(--text-sec);font-size:12px;font-weight:600;"> / '+SECT_MAX+'</span></div><div style="color:var(--text-sec);font-size:11px;margin-top:2px;">已收弟子</div></div>'+
        '<div style="width:1px;background:var(--hair);"></div>'+
        '<div><div style="color:var(--text-main);font-size:20px;font-weight:800;">'+worldCount+'</div><div style="color:var(--text-sec);font-size:11px;margin-top:2px;">已通世界</div></div>'+
        '<div style="width:1px;background:var(--hair);"></div>'+
        '<div class="ph-tap" onclick="window.__phNav(\'achievements\')" style="cursor:pointer;"><div style="color:var(--accent);font-size:20px;font-weight:800;">'+achCount+'</div><div style="color:var(--text-sec);font-size:11px;margin-top:2px;">成就 ›</div></div>'+
      '</div>'+
      '</div>';
    // 视角切换横向条 —— 只列已揭示（有 name）的弟子
    var activeId = head.active && head.active.discipleId;
    var chips = (head.disciples || []).filter(function(x){ return x && x.name; }).map(function(d){
      var sel = d.id === activeId;
      return '<div class="ph-tap" onclick="window.__phSectSetActive(\''+d.id+'\')" '+
        'style="display:inline-flex;align-items:center;gap:6px;padding:6px 12px;margin:2px;'+
        'border-radius:16px;font-size:12.5px;font-weight:600;white-space:nowrap;cursor:pointer;'+
        (sel ? 'background:var(--accent);color:#fff;' : 'background:var(--card-bg);border:1px solid var(--border);color:var(--text-main);')+'">'+
        _sectEmoji(d)+' '+_sectEscape(d.name)+'</div>';
    }).join('');
    var bar = chips.length > 1 ? '<div class="ph-rise" style="margin-bottom:16px;padding:10px 4px;overflow-x:auto;white-space:nowrap;text-align:center;">'+chips+'</div>' : '';
    // 3×3 网格
    var cells = '';
    for (var i = 0; i < SECT_MAX; i++) cells += _sectSlot(head, i);
    var grid = '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:0 4px;">'+cells+'</div>';
    var footer = '<div style="text-align:center;color:var(--text-sec);font-size:12px;margin-top:20px;line-height:1.6;">'+
      '点击弟子格 = 切换活跃 · 查看详情<br>点击 ＋ = 新收弟子（最多 '+SECT_MAX+' 位）</div>';
    return wrap('师门', widget + bar + grid + footer);
  }

  /* -------- 单徒详情 -------- */
  var _sectDetailId = null;  // __phSectTap 会先设它再 nav('sectDetail')
  function _sectEscape(s){
    // 用 charCode 拼实体，避开编辑通道对 HTML entity 的自动反转义
    var AMP = '&' + '#38;', LT = '&' + '#60;', GT = '&' + '#62;', QT = '&' + '#34;', AP = '&' + '#39;';
    var map = { '<': LT, '>': GT, '&': AMP, '"': QT, "'": AP };
    return String(s == null ? '' : s).replace(/[<>&"']/g, function(c){ return map[c]; });
  }
  function scSectDetail(){
    var head = _sectHead();
    if (!head) return wrap('弟子详情','<div style="text-align:center;color:var(--text-sec);padding:40px;">DZDB 未就绪</div>');
    var d = (head.disciples || []).filter(function(x){ return x && x.id === _sectDetailId; })[0];
    if (!d) return wrap('弟子详情','<div style="text-align:center;color:var(--text-sec);padding:40px;">弟子不存在或已被遣散</div>');
    var isActive = d.id === (head.active && head.active.discipleId);
    var worldName = _sectWorldName(head, d.worldId) || '（未指定）';
    var header = '<div style="display:flex;align-items:center;margin:8px 0 20px;position:relative;height:32px;">'+
      '<div class="ph-tap" onclick="window.__phNav(\'sect\')" style="position:absolute;left:0;cursor:pointer;color:var(--accent);font-size:16px;font-weight:500;">‹ 师门</div>'+
      '<b style="flex:1;text-align:center;color:var(--text-main);font-size:18px;font-weight:700;">'+_sectEscape(d.name || '降临中…')+'</b></div>';

    // ===== 分支 A：未揭示（无 name）— 展示"降临中"占位卡 =====
    if (!d.name) {
      var today = (head.meta && head.meta.gameDay) || (head.meta && head.meta.day) || 1;
      var waited = d.summonedAt ? (today - d.summonedAt) : 0;
      var status = d.summonedAt
        ? '等待 AI 在下段剧情中揭示身份'+(waited > 0 ? '（已等待 '+waited+' 日）' : '')
        : '尚未发起寻徒';
      var portraitP = '<div class="ph-rise" style="display:flex;flex-direction:column;align-items:center;padding:30px 20px;background:linear-gradient(160deg,var(--accent-dim),transparent);border:1px dashed var(--border);border-radius:22px;margin-bottom:16px;">'+
        '<div style="font-size:64px;margin-bottom:12px;opacity:.7;">🌌</div>'+
        '<div style="color:var(--text-main);font-size:20px;font-weight:800;letter-spacing:-0.4px;">'+
          '降临中…'+(isActive?' <span style="background:var(--accent);color:#fff;font-size:10px;font-weight:700;padding:2px 6px;border-radius:6px;vertical-align:middle;">活跃</span>':'')+
        '</div>'+
        '<div style="color:var(--text-sec);font-size:12.5px;margin-top:8px;text-align:center;line-height:1.6;">'+_sectEscape(status)+'</div>'+
      '</div>';
      function _lineP(k, v){ return '<div style="display:flex;justify-content:space-between;padding:8px 0;font-size:13px;border-bottom:1px solid var(--hair);"><span style="color:var(--text-sec);">'+k+'</span><span style="color:var(--text-main);font-weight:500;max-width:60%;text-align:right;">'+_sectEscape(v||'—')+'</span></div>'; }
      var infoP = '<div class="ph-rise" style="padding:16px 20px;background:var(--card-bg);border:1px solid var(--border);border-radius:20px;margin-bottom:16px;box-shadow:var(--shadow);">'+
        _lineP('目标世界', worldName) +
        _lineP('招募日',   d.summonedAt ? ('第 '+d.summonedAt+' 日') : '未招募') +
        '<div style="padding:10px 0 4px;font-size:13px;"><div style="color:var(--text-sec);margin-bottom:5px;">寻徒意向</div>'+
        '<div style="color:var(--text-main);font-weight:500;line-height:1.7;">'+_sectEscape(d.summonIntent || '未指定（由 AI 自由揭示）')+'</div></div>'+
      '</div>';
      var actBtnP = isActive
        ? '<button disabled style="flex:1;border:none;border-radius:14px;background:var(--bg);color:var(--text-sec);padding:12px;font-size:14px;font-weight:600;">已活跃</button>'
        : '<button class="ph-press" onclick="window.__phSectSetActive(\''+d.id+'\')" style="flex:1;border:none;border-radius:14px;background:var(--accent);color:#fff;padding:12px;font-size:14px;font-weight:700;cursor:pointer;">设为活跃</button>';
      var opsP = '<div style="display:flex;gap:10px;margin-bottom:14px;">'+actBtnP+'</div>'+
        '<button class="ph-press" onclick="window.__phSectDismiss(\''+d.id+'\')" style="width:100%;border:none;border-radius:14px;background:transparent;border:1px solid #FF3B30;color:#FF3B30;padding:11px;font-size:13px;font-weight:600;cursor:pointer;">取消寻徒</button>';
      var tipP = '<div class="ph-rise" style="padding:12px 16px;margin-bottom:16px;background:var(--card-bg);border:1px solid var(--border);border-radius:14px;color:var(--text-sec);font-size:11.5px;line-height:1.75;">'+
        '💡 <b>寻徒机制</b>：把此位徒弟设为活跃后，向 AI 发送一句剧情推进（如"开始下一段"），AI 会在 <b><状态></b> 块里为该徒弟填入 name/外貌/性格 等属性并推进剧情，届时头像与信息会自动出现。</div>';
      return header + portraitP + infoP + tipP + opsP;
    }

    // ===== 分支 B：已揭示（有 name）— 常规详情卡 =====
    var lv = (d.aff && d.aff.level) || 0, pct = Math.max(0, Math.min(100, (d.aff && d.aff.value) || 0));
    var achList = (d.achievements || []);
    var portrait = '<div class="ph-rise" style="display:flex;align-items:center;padding:20px;background:var(--card-bg);border:1px solid var(--border);border-radius:22px;margin-bottom:16px;box-shadow:var(--shadow);">'+
      '<div style="font-size:48px;margin-right:16px;height:78px;width:78px;border-radius:39px;display:flex;align-items:center;justify-content:center;background:linear-gradient(160deg,var(--accent-dim),transparent);border:1px solid var(--border);flex:0 0 auto;">'+_sectEmoji(d)+'</div>'+
      '<div style="min-width:0;flex:1;">'+
        '<div style="color:var(--text-main);font-size:20px;font-weight:800;letter-spacing:-0.4px;">'+_sectEscape(d.name)+(isActive?' <span style="background:var(--accent);color:#fff;font-size:10px;font-weight:700;padding:2px 6px;border-radius:6px;vertical-align:middle;">活跃</span>':'')+'</div>'+
        '<div style="color:var(--text-sec);font-size:13px;margin-top:5px;">'+_sectEscape(d.mood || d.emotion || '暂无心境')+'</div>'+
        '<div style="color:var(--text-sec);font-size:11.5px;margin-top:6px;">世界：'+_sectEscape(worldName)+' · 年龄 '+(d.age||'?')+' · '+(d.sex||'?')+'</div>'+
      '</div></div>';
    var affBar = '<div class="ph-rise" style="padding:16px 20px;background:var(--card-bg);border:1px solid var(--border);border-radius:20px;margin-bottom:16px;box-shadow:var(--shadow);">'+
      '<div style="display:flex;justify-content:space-between;margin-bottom:8px;color:var(--text-main);font-size:14px;font-weight:700;"><span>羁绊 Lv.'+lv+'</span><span style="color:var(--accent);">'+pct+'%</span></div>'+
      '<div style="height:8px;border-radius:4px;background:var(--bg);overflow:hidden;"><div style="height:100%;width:'+pct+'%;background:linear-gradient(90deg,var(--accent),#5AC8FA);"></div></div></div>';

    // 道侣段位卡片
    var bond = d.bond || { tier: 0, pactItem: '', pactDay: 0, events: [] };
    var bondTier = bond.tier;
    var bondNames = { 0:'未缔约', 6:'灵契', 7:'心印', 8:'同命', 9:'道侣', 10:'共命' };
    var bondEmoji = { 0:'💔', 6:'💎', 7:'🔗', 8:'🌌', 9:'♾️', 10:'👑' };
    var bondEmo = bondEmoji[bondTier] || '💔';
    var bondName = bondNames[bondTier] || '未知段位';
    var bondCard = '';
    if (bondTier >= 6) {
      bondCard = '<div class="ph-rise" style="padding:16px 20px;background:linear-gradient(160deg,rgba(123,108,255,.12),rgba(74,63,214,.06));border:1px solid var(--border);border-radius:20px;margin-bottom:16px;box-shadow:var(--shadow);">'+
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">'+
          '<div style="color:var(--text-main);font-size:14px;font-weight:700;">道侣段位</div>'+
          '<div style="font-size:24px;">'+bondEmo+'</div></div>'+
        '<div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px;">'+
          '<span style="color:var(--text-main);font-size:20px;font-weight:800;">'+_sectEscape(bondName)+'</span>'+
          '<span style="color:var(--text-sec);font-size:12px;">Lv.'+bondTier+'</span></div>'+
        (bond.pactDay ? '<div style="color:var(--text-sec);font-size:11.5px;">缔结于第 '+bond.pactDay+' 日 · 媒介：'+_sectEscape(bond.pactItem)+'</div>' : '')+
        '</div>';
    } else {
      var status = null;
      try { var _db_ = _db(); if (_db_ && _db_.getBondStatus) status = _db_.getBondStatus(d.id); } catch(_){}
      var canUp = status && status.canUpgrade;
      var statusText = status ? status.reason : '好感等级未达 Lv.5';
      var btnHtml = canUp
        ? '<button class="ph-press" onclick="window.__phUpgradeBond(\''+d.id+'\')" style="width:100%;border:none;border-radius:14px;background:linear-gradient(160deg,#7b6cff,#4a3fd6);color:#fff;padding:12px;font-size:14px;font-weight:700;cursor:pointer;box-shadow:0 4px 12px rgba(90,70,220,.35);margin-top:10px;">🌌 晋升道侣段位（消耗逆天道具）</button>'
        : '';
      bondCard = '<div class="ph-rise" style="padding:16px 20px;background:var(--card-bg);border:1px solid var(--border);border-radius:20px;margin-bottom:16px;box-shadow:var(--shadow);">'+
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">'+
          '<div style="color:var(--text-main);font-size:14px;font-weight:700;">道侣段位 · 未缔约</div>'+
          '<div style="font-size:24px;">💔</div></div>'+
        '<div style="color:var(--text-sec);font-size:12.5px;line-height:1.6;margin-bottom:4px;">前置：好感 Lv.5 + 挚爱 + 逆天道具</div>'+
        '<div style="color:'+(canUp?'#34C759':'var(--text-sec)')+';font-size:12px;font-weight:600;">'+_sectEscape(statusText)+'</div>'+
        btnHtml+'</div>';
    }

    function _line(k, v){ return '<div style="display:flex;justify-content:space-between;padding:6px 0;font-size:13px;"><span style="color:var(--text-sec);">'+k+'</span><span style="color:var(--text-main);font-weight:500;max-width:60%;text-align:right;">'+_sectEscape(v||'—')+'</span></div>'; }
    var info = '<div class="ph-rise" style="padding:16px 20px;background:var(--card-bg);border:1px solid var(--border);border-radius:20px;margin-bottom:16px;box-shadow:var(--shadow);">'+
      _line('外貌', d.appearance) + _line('性格', d.personality) + _line('处境', d.plight) + _line('身处', d.locale) + _line('认知', d.cognitionType) + '</div>';
    var achHtml = achList.length
      ? achList.map(function(a){ return '<span style="display:inline-block;margin:3px;padding:5px 10px;font-size:11.5px;font-weight:600;background:var(--accent-dim);color:var(--accent);border-radius:10px;" title="'+_sectEscape(_achDesc(a.id))+'">'+_sectEscape(_achTitle(a.id))+' · 第'+(a.day||1)+'日</span>'; }).join('')
      : '<div style="color:var(--text-sec);font-size:12px;text-align:center;padding:10px;">暂无成就</div>';
    var ach = '<div class="ph-rise" style="padding:16px 20px;background:var(--card-bg);border:1px solid var(--border);border-radius:20px;margin-bottom:16px;box-shadow:var(--shadow);">'+
      '<div style="color:var(--text-main);font-size:14px;font-weight:700;margin-bottom:8px;">徒弟成就 · '+achList.length+'</div>'+achHtml+'</div>';
    // M8：移除"改名"按钮 —— 徒弟名字由 AI 在原世界剧情中确立，宿主不擅改
    var ops = (isActive
      ? '<button disabled style="width:100%;border:none;border-radius:14px;background:var(--bg);color:var(--text-sec);padding:12px;font-size:14px;font-weight:600;margin-bottom:10px;">已活跃</button>'
      : '<button class="ph-press" onclick="window.__phSectSetActive(\''+d.id+'\')" style="width:100%;border:none;border-radius:14px;background:var(--accent);color:#fff;padding:12px;font-size:14px;font-weight:700;cursor:pointer;margin-bottom:10px;">设为活跃</button>')+
      '<button class="ph-press" onclick="window.__phSectDismiss(\''+d.id+'\')" style="width:100%;border:none;border-radius:14px;background:transparent;border:1px solid #FF3B30;color:#FF3B30;padding:11px;font-size:13px;font-weight:600;cursor:pointer;">遣散弟子</button>';
    return header + portrait + affBar + bondCard + info + ach + ops;
  }

  /* -------- 寻徒表单（M8 · 徒弟从诸天万界降临，宿主不决定其身份） -------- */
  function scSectRecruit(){
    var head = _sectHead();
    if (!head) return wrap('寻徒','<div style="text-align:center;color:var(--text-sec);padding:40px;">DZDB 未就绪</div>');
    var named = (head.disciples || []).filter(function(x){ return x && x.name; }).length;
    if (named >= SECT_MAX) return wrap('寻徒','<div style="text-align:center;color:var(--text-sec);padding:40px;">师门已满 ('+SECT_MAX+'/'+SECT_MAX+')</div>');
    var worldOpts = (head.worlds || []).map(function(w){ return '<option value="'+_sectEscape(w.id)+'">'+_sectEscape(w.name||w.id)+'</option>'; }).join('');
    var header = '<div style="display:flex;align-items:center;margin:8px 0 20px;position:relative;height:32px;">'+
      '<div class="ph-tap" onclick="window.__phNav(\'sect\')" style="position:absolute;left:0;cursor:pointer;color:var(--accent);font-size:16px;font-weight:500;">‹ 师门</div>'+
      '<b style="flex:1;text-align:center;color:var(--text-main);font-size:18px;font-weight:700;">诸天寻徒</b></div>';
    function _row(label, ctrl){ return '<div style="margin-bottom:14px;"><div style="color:var(--text-sec);font-size:12.5px;font-weight:600;margin-bottom:6px;">'+label+'</div>'+ctrl+'</div>'; }
    var inputStyle = 'style="width:100%;background:var(--bg);border:1px solid var(--border);border-radius:14px;color:var(--text-main);padding:11px 14px;font-size:14px;outline:none;box-sizing:border-box;"';
    var explain = '<div class="ph-rise" style="padding:14px 16px;margin-bottom:14px;background:var(--accent-dim);border:1px solid var(--border);border-radius:16px;color:var(--text-main);font-size:12.5px;line-height:1.75;">'+
      '<b style="color:var(--accent);">✨ 诸天万界寻徒</b><br>'+
      '徒弟本就存在于某个世界，各有自己的姓名与身世。<br>'+
      '你只需<b>选定目标世界</b>并给一句<b>寻徒意向</b>，接下来 AI 会为你揭示这位有缘之徒是谁。'+
      '</div>';
    var form = '<div class="ph-rise" style="padding:20px;background:var(--card-bg);border:1px solid var(--border);border-radius:22px;box-shadow:var(--shadow);">'+
      _row('目标世界',
        (worldOpts ? '<select id="ph-r-world" '+inputStyle+'>'+worldOpts+'<option value="__new__">＋ 新的世界…</option></select>' :
                     '<div style="color:var(--text-sec);font-size:12px;margin-bottom:6px;">当前无世界，将自动新建</div>')+
        '<input id="ph-r-newworld" placeholder="新世界名（选“新的世界”时填，例：修真界 / 星际联邦）" '+inputStyle+' style="margin-top:8px;">') +
      _row('寻徒意向 · 可留空',
        '<textarea id="ph-r-intent" rows="3" '+inputStyle+' style="min-height:74px;resize:vertical;" placeholder="留白让 AI 自由揭示；或写一句方向提示，例：\n· 一位在剑道上迷失方向的年轻剑修\n· 目前身处生死劫难关头的角色"></textarea>') +
      '<button class="ph-press" onclick="window.__phSectDoRecruit()" style="width:100%;border:none;border-radius:14px;background:var(--accent);color:#fff;padding:13px;font-size:15px;font-weight:700;cursor:pointer;margin-top:6px;">🌌 发起寻徒</button>'+
      '</div>';
    return header + explain + form;
  }

  /* -------- 成就辅助：id → title/desc -------- */
  function _achTitle(id){
    var db = _db();
    if (!db || !db.getAchievementDefs) return id;
    var defs = db.getAchievementDefs();
    for (var i = 0; i < defs.length; i++) { if (defs[i].id === id) return defs[i].title || id; }
    return id;
  }
  function _achDesc(id){
    var db = _db();
    if (!db || !db.getAchievementDefs) return '';
    var defs = db.getAchievementDefs();
    for (var i = 0; i < defs.length; i++) { if (defs[i].id === id) return defs[i].desc || ''; }
    return '';
  }
  /* -------- 成就一览 -------- */
  function scAchievements(){
    var head = _sectHead();
    if (!head) return wrap('成就','<div style="text-align:center;color:var(--text-sec);padding:40px;">DZDB 未就绪</div>');
    var db = _db();
    var defs = (db && db.getAchievementDefs) ? db.getAchievementDefs() : [];
    var hostAch = (head.host && head.host.achievements) || [];
    var hostSet = {}; hostAch.forEach(function(a){ hostSet[a.id] = a; });
    // 徒弟成就汇总：id -> 数组[{name, day}]
    var discAch = {};
    (head.disciples || []).forEach(function(d){
      if (!d) return;
      (d.achievements || []).forEach(function(a){
        if (!discAch[a.id]) discAch[a.id] = [];
        discAch[a.id].push({ name: d.name || '未命名', day: a.day || 1 });
      });
    });
    function _card(def){
      var scope = def.scope;
      var got, detail;
      if (scope === 'host') {
        got = !!hostSet[def.id];
        detail = got ? ('已解锁 · 第 '+(hostSet[def.id].day||1)+' 日') : '未解锁';
      } else {
        var arr = discAch[def.id] || [];
        got = arr.length > 0;
        detail = got ? ('已由 '+arr.length+' 位弟子解锁：'+arr.map(function(x){return x.name;}).join('、')) : '未解锁';
      }
      var color = got ? 'var(--accent)' : 'var(--text-sec)';
      var bg = got ? 'linear-gradient(160deg,rgba(0,122,255,.12),rgba(88,86,214,.06))' : 'var(--card-bg)';
      var badge = scope === 'host' ? '宿主' : '弟子';
      var aiFlag = def.aiClaimable ? ' <span style="font-size:10px;color:var(--text-sec);border:1px solid var(--border);padding:1px 5px;border-radius:6px;margin-left:4px;">AI</span>' : '';
      return '<div class="ph-rise" style="padding:14px 16px;margin-bottom:10px;background:'+bg+';border:1px solid var(--border);border-radius:16px;'+(got?'':'opacity:.72;')+'">'+
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">'+
          '<div style="color:var(--text-main);font-size:14px;font-weight:700;">'+_sectEscape(def.title||def.id)+aiFlag+'</div>'+
          '<span style="font-size:10.5px;color:var(--text-sec);border:1px solid var(--border);padding:1px 6px;border-radius:6px;">'+badge+'</span></div>'+
        '<div style="color:'+color+';font-size:12px;">'+detail+'</div>'+
        '<div style="color:var(--text-sec);font-size:11px;margin-top:4px;line-height:1.5;">'+_sectEscape(def.desc||'')+'</div>'+
        '</div>';
    }
    var body = defs.length ? defs.map(_card).join('') : '<div style="text-align:center;color:var(--text-sec);padding:40px;">未定义</div>';
    var header = '<div style="display:flex;align-items:center;margin:8px 0 20px;position:relative;height:32px;">'+
      '<div class="ph-tap" onclick="window.__phNav(\'sect\')" style="position:absolute;left:0;cursor:pointer;color:var(--accent);font-size:16px;font-weight:500;">‹ 师门</div>'+
      '<b style="flex:1;text-align:center;color:var(--text-main);font-size:18px;font-weight:700;">成就 · '+defs.length+'</b></div>';
    return header + body;
  }

  /* ============================================================
   * 【M5】数据库管理面板 —— 诊断 / 瘦身 / 导入导出 UI
   * ------------------------------------------------------------
   * 三张卡：Diagnose / GC / Export+Import
   * 操作结果通过 innerHTML 更新对应结果区，不重渲整屏（保留输入）
   * ============================================================ */
  function _dbaStatusLight(status){
    var color = status === 'ok' ? '#34C759' : (status === 'warn' ? '#FF9500' : '#FF3B30');
    var label = status === 'ok' ? '正常' : (status === 'warn' ? '警告' : '错误');
    return '<span style="display:inline-flex;align-items:center;gap:5px;">'+
      '<span style="width:8px;height:8px;border-radius:4px;background:'+color+';box-shadow:0 0 6px '+color+'80;"></span>'+
      '<span style="font-size:11.5px;color:'+color+';font-weight:600;">'+label+'</span></span>';
  }
  function scDbAdmin(){
    var db = _db();
    if (!db || !db.diagnose) return wrap('数据管理','<div style="text-align:center;color:var(--text-sec);padding:40px;">DZDB 未就绪或版本过旧</div>');
    // 内嵌 CSS + wrap 顶栏
    var css = '<style>'+
      '.dba-card{padding:18px;background:var(--card-bg);border:1px solid var(--border);border-radius:20px;margin-bottom:16px;box-shadow:var(--shadow);}'+
      '.dba-h{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;}'+
      '.dba-title{color:var(--text-main);font-size:15px;font-weight:800;letter-spacing:-0.3px;}'+
