  function renderScreen(page, arg) {
    hideLoading();
    var el = D.getElementById('ph-screen'); if (!el) return;
    var dock = D.getElementById('ph-dock');
    if (sel.active && sel.page !== page) selExit();
    if (page==='chat') {
      el.style.paddingBottom = '0';
      if (dock) dock.style.display = 'none';
      el.innerHTML = scChat(arg);
      var lg = D.getElementById('ph-chatlog'); if (lg) lg.scrollTop = lg.scrollHeight;
      return;
    }
    el.style.paddingBottom = '108px';
    if (dock) dock.style.display = 'flex';
    var map = { home:scHome, disciple:scDisciple, dbag:scDiscipleBag, shop:scShop, wallet:scWallet, news:scNews, bag:scBag, sms:scSMS, settings:scSettings, database:scDatabase, blacklist:scBlacklist, sect:scSect, sectDetail:scSectDetail, sectRecruit:scSectRecruit, achievements:scAchievements, dbadmin:scDbAdmin, graph:scRelationGraph };
    el.innerHTML = (map[page]||scHome)();
    // Live2D：进入徒弟页时初始化；离开时销毁旧实例（防 WebGL context 泄露）
    if(page==='disciple'){
      var d2l = load();
      if(d2l.live2d && d2l.live2d.enabled !== false){
        setTimeout(function(){ l2dInit('ph-l2d-canvas', d2l.live2d.modelUrl||''); }, 80);
      }
    } else {
      l2dDestroy();
    }
  }

