  // 保存 head 的公共辅助：直接走 DZDB
  function _sectSaveHead(head){
    var db = _db();
    if (!db || !db.load || !db.save) { toast('error','DZDB 未就绪'); return false; }
    var raw = db.load();
    raw.head = head;
    db.save(raw);
    return true;
  }
  function _sectGenId(prefix){
    return prefix + '_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,7);
  }
  // 点击弟子格：如已活跃→打开详情；否则先设活跃再打开
  W.__phSectTap = function(discipleId){
    var db = _db(); if (!db || !db.load) { toast('error','DZDB 未就绪'); return; }
    var head = db.load().head;
    var d = (head.disciples||[]).filter(function(x){return x&&x.id===discipleId;})[0];
    if (!d) { toast('warning','弟子不存在'); renderScreen('sect'); return; }
    var activeId = head.active && head.active.discipleId;
    if (activeId !== discipleId) {
      head.active = head.active || {}; head.active.discipleId = discipleId;
      _sectSaveHead(head);
      toast('success','已切换活跃弟子：'+(d.name||'未命名'));
    }
    _sectDetailId = discipleId;
    renderScreen('sectDetail');
  };
  W.__phSectSetActive = function(discipleId){
    var db = _db(); if (!db || !db.load) return;
    var head = db.load().head;
    head.active = head.active || {}; head.active.discipleId = discipleId;
    if (_sectSaveHead(head)) { toast('success','已设为活跃'); renderScreen('sectDetail'); }
  };
  // M8：__phSectRename 已废弃 —— 徒弟名字由 AI 在原世界剧情中确立，宿主不再手动改名。
  // 若旧存档意外调用，静默 no-op（不再暴露入口按钮，可保留兼容占位）。
  W.__phSectRename = function(){ toast('info','徒弟名字由剧情决定，无需手动改名'); };
  W.__phSectRenameHost = function(){
    var db = _db(); if (!db || !db.load) return;
    var head = db.load().head;
    var cur = (head.host && head.host.name) || '';
    var newName = W.prompt('宿主名号：', cur);
    if (newName === null) return;
    head.host = head.host || {}; head.host.name = newName.trim();
    if (_sectSaveHead(head)) { toast('success','已保存'); renderScreen('sect'); }
  };
  W.__phSectDismiss = function(discipleId){
    var db = _db(); if (!db || !db.load) return;
    var head = db.load().head;
    var d = (head.disciples||[]).filter(function(x){return x&&x.id===discipleId;})[0];
    if (!d) return;
    if (!W.confirm('确认遣散「'+(d.name||'未命名')+'」？此操作不可撤销。')) return;
    head.disciples = (head.disciples||[]).filter(function(x){return x&&x.id!==discipleId;});
    // 若活跃是它，回退到第一位
    if (head.active && head.active.discipleId === discipleId) {
      head.active.discipleId = (head.disciples[0] && head.disciples[0].id) || null;
    }
    if (_sectSaveHead(head)) { toast('success','已遣散'); renderScreen('sect'); }
  };
  W.__phSectRecruit = function(){ renderScreen('sectRecruit'); };
  W.__phSectDoRecruit = function(){
    // M8：不再收集 name/sex/age/外貌/性格 —— 那些是徒弟自身在原世界的属性，由 AI 揭示
    var wId    = (D.getElementById('ph-r-world')||{}).value||'';
    var wNew   = ((D.getElementById('ph-r-newworld')||{}).value||'').trim();
    var intent = ((D.getElementById('ph-r-intent')||{}).value||'').trim();
    var db = _db(); if (!db || !db.load) { toast('error','DZDB 未就绪'); return; }
    var head = db.load().head;
    head.disciples = head.disciples || [];
    // 已"揭示"的徒弟计数（有名字 = 已显现），未显现的占位不占额
    var namedCount = head.disciples.filter(function(x){ return x && x.name; }).length;
    if (namedCount >= SECT_MAX) { toast('warning','师门已满'); return; }
    // 世界处理：新建 / 无 / 已选
    var worldId = wId;
    if (!worldId || worldId === '__new__') {
      if (!wNew) { toast('warning','请填写目标世界'); return; }
      var newWorld = { id: _sectGenId('w'), name: wNew, tone:'', era:'', npcs:[], timeline:[], places:[], factions:[], genre:'' };
      head.worlds = head.worlds || []; head.worlds.push(newWorld);
      worldId = newWorld.id;
    }
    // 建"待揭示"占位徒弟：name/appearance/... 全部空，由 AI 在下段剧情揭示
    var today = (head.meta && head.meta.gameDay) || (head.meta && head.meta.day) || 1;
    var nd = {
      id: _sectGenId('d'), worldId: worldId,
      name:'', age:'', sex:'', appearance:'', personality:'',
      world:'', plight:'', cognitionType:'', emotion:'calm', mood:'',
      status:'待揭示', storyline:'', locale:'', belongings:[], backlog:[],
      aff: { level: 0, value: 0 }, achievements: [],
      summonIntent: intent, summonedAt: today, revealed: false
    };
    // 首个空占位（未招募的 d_default）→ 覆盖，继承 id 让 active 无缝迁移
    var slotIdx = -1;
    for (var i = 0; i < head.disciples.length; i++) {
      var x = head.disciples[i];
      if (!x || (!x.name && !x.summonIntent && !x.summonedAt)) { slotIdx = i; break; }
    }
    if (slotIdx >= 0) {
      var oldId = head.disciples[slotIdx] && head.disciples[slotIdx].id;
      if (oldId) nd.id = oldId;
      head.disciples[slotIdx] = nd;
    } else {
      head.disciples.push(nd);
    }
    // 活跃：无活跃或指向已消失的 id → 设为新占位（AI 揭示时会自然填充）
    head.active = head.active || {};
    var stillHas = head.disciples.some(function(x){ return x && x.id === head.active.discipleId; });
    if (!head.active.discipleId || !stillHas) head.active.discipleId = nd.id;
    if (_sectSaveHead(head)) {
      toast('success','🌌 已发起寻徒，等待下段剧情揭示');
      // 不再立即调 scanAchievements —— d_meet/h_first 会在 AI 揭示 name 时由 dbCommit 钩子触发
      renderScreen('sect');
    }
  };

  // 道侣晋升：从背包选择逆天道具
  W.__phUpgradeBond = function(discipleId) {
    var db = _db();
    if (!db || !db.load || !db.getBondStatus || !db.upgradeBond) {
      toast('error', 'DZDB 未就绪'); return;
    }
    var status = db.getBondStatus(discipleId);
    if (!status) { toast('error', '徒弟不存在'); return; }
    if (!status.canUpgrade) { toast('warning', status.reason); return; }

    var head = db.load().head;
    var bag = head.phone.bag || [];
    // 按 desc 含"逆天"或 tier=逆天 筛选
    var seen = {};
    var allItems = [];
    bag.forEach(function(x) {
      if (!x || !x.name) return;
      var match = (x.desc && x.desc.indexOf('逆天') >= 0) || x.tier === '逆天';
      if (!match) return;
      if (seen[x.name]) return;
      seen[x.name] = true;
      allItems.push(x);
    });

    if (!allItems.length) {
      toast('warning', '背包中没有逆天级道具。请先在商城中购买或在剧情中获得。');
      return;
    }

    var host = D.getElementById('ph-mask');
    if (!host) return;
    var old = D.getElementById('ph-bond-picker');
    if (old) old.remove();

    var listHtml = allItems.map(function(it) {
      var escName = (it.name || '').replace(/'/g, "\\'");
      return '<div class="ph-press" onclick="window.__phDoUpgradeBond(\''+discipleId+'\',\''+escName+'\')" '+
        'style="display:flex;justify-content:space-between;align-items:center;padding:14px 16px;margin-bottom:8px;'+
        'background:var(--card-bg);border:1px solid var(--border);border-radius:16px;cursor:pointer;">'+
        '<div><div style="color:var(--text-main);font-size:15px;font-weight:600;">'+_sectEscape(it.name)+'</div>'+
        '<div style="color:var(--text-sec);font-size:12px;margin-top:2px;">'+(it.desc||'')+' · x'+(it.qty||1)+'</div></div>'+
        '<span style="color:var(--accent);font-size:13px;font-weight:600;">选择 ›</span></div>';
    }).join('');

    var box = D.createElement('div');
    box.id = 'ph-bond-picker';
    box.setAttribute('style', 'position:fixed;inset:0;z-index:2147483647;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.5);');
    box.innerHTML = '<div class="ph-rise" style="width:82%;max-width:320px;background:var(--card-bg);border:1px solid var(--border);border-radius:24px;padding:24px 20px;box-shadow:0 24px 50px rgba(0,0,0,0.35);">'+
      '<div style="color:var(--text-main);font-size:17px;font-weight:700;margin-bottom:4px;text-align:center;">选择晋升媒介</div>'+
      '<div style="color:var(--text-sec);font-size:12px;text-align:center;margin-bottom:16px;">选择一个逆天级道具作为契约媒介</div>'+
      listHtml+
      '<button class="ph-press" onclick="this.closest(\'#ph-bond-picker\').remove()" style="width:100%;border:none;border-radius:14px;background:var(--bg);color:var(--text-sec);padding:12px;font-size:14px;font-weight:600;cursor:pointer;margin-top:8px;">取消</button></div>';
    host.appendChild(box);
  };

