  // 存最近一次导出结果，供"复制"按钮使用
  var _dbaExportCache = '';
  function _dbaSetHTML(id, html){
    var el = D.getElementById(id);
    if (el) el.innerHTML = html;
  }
  function _dbaSetVal(id, val){
    var el = D.getElementById(id);
    if (el) el.value = val;
  }
  function _dbaFmtIssues(layers){
    var out = [];
    Object.keys(layers).forEach(function(k){
      var lyr = layers[k];
      var head = '[' + k + '] ' + lyr.status;
      out.push(head);
      (lyr.issues || []).forEach(function(iss){
        out.push('  · ' + iss.code + (iss.fixable?' (可修)':'') + ' — ' + iss.msg);
      });
    });
    return out.join('\n');
  }
  W.__phDbaDiag = function(){
    var db = _db();
    if (!db || !db.diagnose) { toast('error','DZDB 未就绪'); return; }
    try {
      var diag = db.diagnose();
      // 灯：4 层 + overall
      var lights = ['schema','structure','ref','consistency'].map(function(k){
        return _dbaStatusLight((diag.layers[k]||{}).status || 'error') + '<span style="color:var(--text-sec);font-size:10px;margin-left:3px;">'+k+'</span>';
      }).join('');
      _dbaSetHTML('dba-diag-lights', lights);
      var summary = '总体：' + diag.overall + '\n\n' + _dbaFmtIssues(diag.layers);
      _dbaSetHTML('dba-diag-result', _sectEscape(summary));
      toast(diag.overall==='ok'?'success':'warning', '诊断完成：'+diag.overall);
    } catch(e){
      _dbaSetHTML('dba-diag-result', '诊断异常：' + e.message);
      toast('error','诊断失败');
    }
  };
  W.__phDbaAutoFix = function(){
    var db = _db();
    if (!db || !db.autoFix) { toast('error','DZDB 未就绪'); return; }
    if (!W.confirm('确认执行自动修复？将重绑活跃引用并触发结构保险。')) return;
    try {
      var r = db.autoFix();
      var msg = '修复完成\n剩余问题数：' + r.remaining + '\n修复后状态：' + r.overall;
      _dbaSetHTML('dba-diag-result', msg);
