      toast('success','自动修复完成');
    } catch(e){
      _dbaSetHTML('dba-diag-result', '修复异常：' + e.message);
      toast('error','修复失败');
    }
  };
  W.__phDbaGC = function(){
    var db = _db();
    if (!db || !db.gc) { toast('error','DZDB 未就绪'); return; }
    var hist = parseInt((D.getElementById('dba-gc-hist')||{}).value||'200', 10);
    var snap = parseInt((D.getElementById('dba-gc-snap')||{}).value||'3',   10);
    var drop = !!((D.getElementById('dba-gc-drop')||{}).checked);
    if (drop && !W.confirm('确认删除未引用的世界？此操作不可撤销。')) return;
    try {
      var stat = db.gc({
        trimHistoryMax: isNaN(hist) ? 200 : hist,
        keepSnapshots:  isNaN(snap) ? 3   : snap,
        dropUnusedWorlds: drop,
        dropOrphanNpc: true
      });
      var text = '瘦身完成：\n'+
        '  history 裁剪：' + stat.removedHistory + '\n' +
        '  快照裁剪：' + stat.removedSnapshots + '\n' +
        '  孤儿 NPC 删除：' + stat.removedNpc + '\n' +
        '  未引用世界删除：' + stat.removedWorlds;
      _dbaSetHTML('dba-gc-result', _sectEscape(text));
      toast('success','瘦身完成');
    } catch(e){
      _dbaSetHTML('dba-gc-result', '瘦身异常：' + e.message);
      toast('error','瘦身失败');
    }
  };
