  W.__phSelExtract = function(){
    if(!sel.keys.length){ toast('warning','未选择'); return; }
    var d=load(), names=sel.keys.slice(), parts=[], descs=[];
    names.forEach(function(nm){
      var item=d.bag.find(function(x){return x.name===nm;});
      var q=sel.qty[nm]||1; var got=bagDeduct(d,nm,q);
      if(got){
        parts.push(nm+(got>1?('x'+got):''));
        if(item&&item.desc) descs.push('【'+nm+'】'+item.desc);
      }
    });
    var cog=d.meta.cognition||'懵懂'; save(d);
    if(!parts.length){ toast('warning','背包无对应道具'); return; }
    var descStr = descs.length ? '（道具效果说明：'+descs.join('；')+'）' : '';
    var how=(cog==='觉醒')?'宿主已觉醒，请描写这批物品直接凭空出现在宿主面前。':'宿主尚未完全确信系统为真（认知：'+cog+'），请描写这批物品以看似合理的方式送达现实（快递、门口包裹、意外中奖等），像巧合。';
    sendAction('〔系统·提取到现实〕宿主将修仙界的【'+parts.join('、')+'】一并提取到现实。'+descStr+how+'请严格按照上述道具描述来描写其效果与宿主的反应。');
    selExit(); W.__phClose();
  };
  W.__phSelClear = function(){
    var d=load(), g=sel.page, keys=sel.keys.slice(), n=keys.length;
    if(!n){ toast('warning','未选择'); return; }
    if(g==='bag') keys.forEach(function(nm){ var i=d.bag.findIndex(function(x){return x.name===nm;}); if(i>=0)d.bag.splice(i,1); });
    else if(g==='news') d.phone.news=(d.phone.news||[]).filter(function(_,i){return keys.indexOf('news'+i)<0;});
    else if(g==='rebate') d.econ.rebateLog=(d.econ.rebateLog||[]).filter(function(_,i){return keys.indexOf('rebate'+i)<0;});
    save(d); toast('success','已清除 '+n+' 项');
    selExit(); renderScreen(g);
  };
  W.__phSelBuy = function(){
    var d=load(), bought=0, cost=0, keys=sel.keys.slice();
    keys.forEach(function(k){ var i=parseInt(k.replace('shop',''),10); var g=(d.phone.shop||[])[i]; if(!g||g.stock<=0)return;
      if(d.econ.balance>=g.price){ d.econ.balance-=g.price; d.econ.coin+=g.price; g.stock-=1; var f=d.bag.find(function(x){return x.name===g.name;}); if(f)f.qty=(f.qty||1)+1; else d.bag.push({name:g.name,desc:g.desc||'',qty:1}); bought++; cost+=g.price; } });
    save(d);
    toast(bought?'success':'warning', bought?('购买 '+bought+' 件，花费 '+money(cost)):'余额不足或无库存');
    var p=sel.page; selExit(); renderScreen(p);
  };

  /* ============================================================
   * 事件 — 保留项，未改动
   * ============================================================ */
  function injectBtn() {
    var blocks = D.querySelectorAll('#chat .mes .mes_text');
    var last = blocks[blocks.length-1];
    if (last && !last.querySelector('.__ph-btn')) {
      var b = D.createElement('div');
      b.className = '__ph-btn'; b.style.cssText = 'text-align:center;margin:14px 0 4px;';
      b.innerHTML = '<button onclick="window.__phOpen()" style="padding:11px 28px;border:none;border-radius:24px;background:linear-gradient(145deg,#7b6cff,#4a3fd6);color:#fff;font-size:14px;font-weight:600;letter-spacing:2px;cursor:pointer;box-shadow:0 6px 18px rgba(90,70,220,.45);">📱 打开手机</button>';
      last.appendChild(b);
    }
  }
  function hook(mid) {
    var db = _db();
    try {
      var m=getChatMessages(mid); var t=m&&m[0]&&m[0].message;
      if(t){
        if(db && db.parse){ db.parse(t, mid); if(db.snapshot) db.snapshot(mid); }
        else { parseSceneHeader(t); parseSetCommands(t); var _d=load(); _d.meta.lastCatchUp=mid; saveRaw(_d); }
      }
    }
    catch(e){ try{ var m2=(typeof getChatMessage==='function')?getChatMessage(mid):null; if(m2&&m2.message){ if(db&&db.parse) db.parse(m2.message,mid); else { parseSceneHeader(m2.message); parseSetCommands(m2.message);} } }catch(_){} }
    setTimeout(injectBtn,150);
    if(!(db && db.snapshot)) setTimeout(function(){ writeFloorSnap(mid); }, 200);
    try {
      var d = load();
      if (d.auto && d.auto.enabled) {
        d.auto.counter = (d.auto.counter || 0) + 1;
        var need = Math.max(1, parseInt(d.auto.interval, 10) || 3);
        if (d.auto.counter >= need) { d.auto.counter = 0; saveRaw(d); setTimeout(autoUpdate, 300); }
        else saveRaw(d);
      }
    } catch (e) { console.error('[徒弟系统] 计数失败', e); }
  }
  try {
    eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, hook);
    eventOn(tavern_events.CHAT_CHANGED, function(){ load(); setTimeout(injectBtn,300); });
    if (tavern_events.MESSAGE_SWIPED) eventOn(tavern_events.MESSAGE_SWIPED, function(mid){ var db=_db(); var target=(parseInt(mid,10)||0)-1; if(db&&db.restore){ db.restore(target); if(D.getElementById('ph-mask')) renderScreen('home'); } else restoreFromFloor(target); });
    if (tavern_events.MESSAGE_DELETED) eventOn(tavern_events.MESSAGE_DELETED, function(){ try{ var last=getLastMessageId(); var db=_db(); if(db&&db.restore){ db.restore(last); if(D.getElementById('ph-mask')) renderScreen('home'); } else restoreFromFloor(last); }catch(_){} });
    /* 【M6+M9】成就声明 + 视角切换 —— MESSAGE_RECEIVED 事件里扫 <成就>/<视角> 标签 */
    if (tavern_events.MESSAGE_RECEIVED) eventOn(tavern_events.MESSAGE_RECEIVED, function(mid){
      try { parseAchievementDeclarations(mid); } catch(e){ console.warn('[徒弟系统] 成就解析失败', e); }
      try { parseViewSwitch(mid); }          catch(e){ console.warn('[徒弟系统] 视角切换失败', e); }
    });
  } catch(e){ console.error('[徒弟系统] 事件绑定失败', e); }

  /* ============================================================
   * 【M9】AI 视角切换解析器
   * ------------------------------------------------------------
   * 从消息文本抠 <视角 id="XXX"/> 或 <视角 id="XXX" />，
   * 找到 disciples 里对应 id 的徒弟，调 __phSectSetActive 切换活跃视角。
   * ============================================================ */
  var VIEW_TAG_RE = /<视角\s+id="([^"]+)"\s*\/?>/g;
  function parseViewSwitch(mid){
    if (typeof getChatMessages !== 'function') return;
    var arr;
    try { arr = getChatMessages(mid); } catch(_) { return; }
    if (!arr || !arr.length) return;
    var msg = arr[0];
    if (!msg || (msg.role && msg.role !== 'assistant')) return;
    var text = msg.message || msg.mes || '';
    if (!text || text.indexOf('<视角') < 0) return;
    var db = _db();
    if (!db || !db.load) return;
    var head = db.load().head;
    if (!head || !head.disciples) return;
    var m, switched = false;
    VIEW_TAG_RE.lastIndex = 0;
    while ((m = VIEW_TAG_RE.exec(text)) !== null) {
      var targetId = m[1];
      // 检查目标 id 是否在 disciples 里
      var found = (head.disciples || []).some(function(x){ return x && x.id === targetId; });
      if (!found) continue;
      if (head.active && head.active.discipleId === targetId) continue; // 已是当前视角
      head.active = head.active || {}; head.active.discipleId = targetId;
      try { _sectSaveHead(head); } catch(_){}
      switched = true;
    }
    if (switched) {
      toast('info', '👁 视角已切换');
    }
  }
  /* ============================================================
   * 【M6】AI 成就声明解析器
   * ------------------------------------------------------------
   * 从消息文本抠 <成就 id="XXX" 对象="disciple|host"/>，
   * 调 DZDB.claimAchievementByAI（白名单只放 d_awaken/d_trial/h_legend），
   * 非白名单/重复解锁会被静默 drop。
   * ============================================================ */
  var ACH_TAG_RE = /<成就\s+id="([^"]+)"\s+对象="(disciple|host)"\s*\/?>/g;
  function parseAchievementDeclarations(mid){
    if (typeof getChatMessages !== 'function') return;
    var arr;
    try { arr = getChatMessages(mid); } catch(_) { return; }
    if (!arr || !arr.length) return;
    var msg = arr[0];
    if (!msg || (msg.role && msg.role !== 'assistant')) return;
    var text = msg.message || msg.mes || '';
    if (!text || text.indexOf('<成就') < 0) return;
    var db = _db();
    if (!db || !db.claimAchievementByAI) return;
    var m, claimed = [], seen = {};
    ACH_TAG_RE.lastIndex = 0;
    while ((m = ACH_TAG_RE.exec(text)) !== null) {
      var id = m[1], scope = m[2];
      var key = id + '|' + scope;
      if (seen[key]) continue; seen[key] = true;
      try {
        var ok = db.claimAchievementByAI(id, scope);
        if (ok) claimed.push(id);
      } catch(_){}
    }
    if (claimed.length) {
      toast('success', '🏆 成就解锁：' + claimed.join('、'));
    }
  }

  /* 【P4.7】等待 DB Core 就绪再初始化（两脚本加载顺序无关） */
  var _booted = false;
  function _boot(){ if(_booted) return; _booted = true; load(); setTimeout(injectBtn, 500); }
  if (W.DZDB && W.DZDB.ready && W.DZDB.ready.then) { W.DZDB.ready.then(_boot); setTimeout(_boot, 1500); }
  else { _boot(); }
});
